programs.sol:
"""A coarse Japanese-text and typography predictor, not a word lookup.

Recent kana identify Japanese-like context. Single-kanji tokens and longer
all-kanji tokens then get different averages based on their first character's
Unihan radical. Decorative marks get larger positive values. These are broad proxies:
individual words within a family can have very different native activations.
"""
from functools import lru_cache
import regex
import unihan

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
HAN = regex.compile(r'\p{Script=Han}+')

# Absolute group averages for a one-character kanji token.
SINGLE_KANJI = {
    'legs': 5.0,       # 儿
    'say': -1.6,       # 曰, not the speech radical 言
    'eye': 0.7,        # 目
    'woman': 0.8,      # 女
    'run': -1.0,       # 走
    'enclosure': -1.0, # 囗
    'city': 1.7,       # 邑
    'hand': -0.4,      # 手
    'feather': -1.3,   # 羽
}
MULTI_KANJI = {'woman': 3.7, 'square': 2.0, 'hand': -0.65}


@lru_cache(maxsize=32768)
def shape_values(text):
    """Return the non-Japanese and Japanese predictions for this token."""
    if HAN.fullmatch(text):
        radical = unihan.radical(text[0])
        name = unihan.radical_name(radical) if radical else ''
        groups = SINGLE_KANJI if len(text) == 1 else MULTI_KANJI
        return 0.0, groups.get(name, 0.27)
    if any(c in '★☆' for c in text):
        return 0.65, 2.0
    if any(c in '○●◎' for c in text):
        return 0.5, 4.0
    if any(c in '◇◆□■△▲▽▼▷◁' for c in text):
        return 0.0, 1.9
    if '※' in text:
        return 0.8, 2.8
    if any(c in '…⋯' for c in text):
        return -0.15, 3.5
    if text and all(c in '・·･' for c in text):
        return (0.95, 2.7) if len(text) > 1 else (0.0, 0.8)
    if '【' in text:
        return 0.65, 5.6
    if '】' in text:
        return 0.0, 1.15
    if any(c in '「『' for c in text):
        return 0.05, 0.5
    if any(c in '」』' for c in text):
        return 0.05, 0.28
    return (0.0, -0.035) if KANA.search(text) else (0.0, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else 0.0
    text = prefix.token_strings[-1].strip()
    recent = 0.9 * recent + float(bool(KANA.search(text)))
    outside, japanese = shape_values(text)
    value = japanese if recent > 1.0 else outside
    return (doc, recent), value

programs.haiku:
"""layers.1.mlp.down_proj:1472, a word-initial kanji detector with a noun/verb sign.

What it does: the component fires on a single kanji that starts a new word, i.e. a kanji
written right after hiragana or katakana (e.g. の|仕事, に|先, を|撮影). Its sign depends on
what kind of word the kanji usually begins:
  * noun-like kanji (役割, 仕事, 元気, 先日, 幅広い, 講座, 活動, 残念...) push it positive;
  * verb-stem kanji (書く, 見る, 来る, 走る, 撮る, 終わる...) push it negative;
  * other kanji after kana get a small positive value.
Decorative symbols that open a list or heading (◎ ○ ★ ☆ ※ ◆ ▼ 【 ・ … 〜) also get a
small positive value. Everything else predicts 0. Kanji after another kanji, or after
punctuation, predict 0, as the component is near zero there.

Plain-language caveat: the lists are hand-made from the component's largest activations on
training text, and the component is mostly lexical, so this is a coarse explanation.
"""

READS = ()

# Kanji that usually begin a noun or noun compound (positive).
NOUN_INITIAL = set(
    "先幅元仕相講活役裏奥仲残世契状妥週形実店種注幕姿筋範株跡稼昇旬芽旦米調場皆氏敷陣刃賞辞容誰誕憧芸翌困夢親今際確逆勤柔薄依荒訪職渡普納試選横枯若昔陰生声朝様側返旧部後村当課適充息底"
)
# Kanji that are usually the stem of a verb or adjective (negative).
VERB_STEM = set(
    "撮組終書回断来走見座習始描採増吊履乗寝替触歌買作争徒曲肘歩掛緩汚泳診怒輝購構療貸臨含抑競防護直笑呼探縮勉遊尽練遭停積送消攻掃享升焦演浮慰祈接留製写求言察導抜急驚抱搭産準並思切減吸答参止吹"
)
# Decorative and list-marker symbols (small positive).
SYMBOLS = set("◎○●★☆※◆▼■□◇・･·…〜～＜〈↓【『℃")
KANA = set(
    "ぁあぃいぅうぇえぉおかがきぎくぐけげこごさざしじすずせぜそぞただちぢっつづてでとどなにぬねのはばぱひびぴふぶぷへべぺほぼぽまみむめもゃやゅゆょよらりるれろゎわゐゑをんゔゕゖ"
    "ァアィイゥウェエォオカガキギクグケゲコゴサザシジスズセゼソゾタダチヂッツヅテデトドナニヌネノハバパヒビピフブプヘベペホボポマミムメモャヤュユョヨラリルレロヮワヰヱヲンヴヵヶ"
)


def _is_kanji(s):
    return len(s) == 1 and "一" <= s <= "鿿"


def _is_kana(s):
    return len(s) > 0 and all(ch in KANA for ch in s)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    value = 0.0
    if tok in SYMBOLS:
        value = 1.5
    elif _is_kanji(tok) and _is_kana(prev):
        if tok in NOUN_INITIAL:
            value = 2.5
        elif tok in VERB_STEM:
            value = -1.5
        else:
            value = 0.4
    return carry, float(value)

programs.sol:
"""Positive on short d-h fragments; negative on English HAVE/HAD continuations.

The spelling pulse is strongest when h ends the fragment, and decays along
following pieces of the same word. Cyrillic д-х is treated as d-h too.
The negative rules distinguish 'had been', 'had better', aspect adverbs,
and verb forms. Separate rules cover D. H. initials and middle-dot runs.
Only three previous tokens and one decaying pulse are kept.
"""
from functools import lru_cache
from anyascii import anyascii
import regex
import wordnet

READS = ()
PERFECT_MODIFIERS = {'already', 'always', 'ever', 'never', 'recently', 'previously',
                     'yet', 'not'}
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}')

@lru_cache(maxsize=65536)
def spelling(token):
    if CYRILLIC.search(token):
        return anyascii(token).lower().replace('kh', 'h')
    return token.lower()

@lru_cache(maxsize=65536)
def word_kind(word):
    pos = wordnet.parts_of_speech(word) if word.isascii() and word.isalpha() else ()
    verb = 'verb' in pos
    inflected = (verb and not word.endswith('ing') and
                 any(base != word for base in wordnet.base_forms(word)))
    return inflected, 'adverb' in pos, verb


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = second = third = ''
        echo = 0.0
    else:
        _, previous, second, third, echo = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev, prev2, prev3 = (s.strip().lower().replace('’', "'")
                         for s in (previous, second, third))
    inflected, adverb, verb = word_kind(word)
    boundary = token[:1].isspace()

    # A d followed by h, within a token or across its edge.
    fragment = spelling(token).strip()
    onset = spelling(token).lstrip("-'’")
    pulse = 0.0
    if 'dh' in fragment:
        pulse = max(0.0, 6.0 - 3.0 * len(fragment.rsplit('dh', 1)[1]))
        if token.strip().isupper():
            pulse *= 0.6 if boundary else 1.2
        elif fragment == 'dh' and token.strip().islower():
            pulse *= 0.75
    if spelling(previous).endswith('d') and onset.startswith('h'):
        strength = max(0.0, 9.0 - 3.0 * (len(onset) - 1))
        # Apostrophes and compound-word hyphens separate the letters.
        if token.startswith(("'", '’')):
            strength *= 0.18 if len(prev) == 1 else 0.0
        elif token.startswith('-'):
            strength *= 0.6 if len(prev) <= 3 else 0.0
        pulse += strength
    if CYRILLIC.search(token):
        pulse *= 0.8
    if boundary or not token[:1].isalpha():
        echo = 0.0
    echo = pulse + 0.45 * echo
    value = 0.002 + echo
    if word == 'h' and token.strip().isupper():
        if (prev == 'd' and boundary) or (prev == '.' and prev2 == 'd'):
            value += 4.0  # Adjacent D. H. initials; do not echo into the surname.

    # Perfect-tense context, including short intervening modifiers.
    if word == 'been':
        value -= {'had': 4.0, 'having': 2.2, 'has': 0.25, 'have': 0.11,
                  "'ve": 0.5, "'d": 4.0}.get(
                      prev, 2.4 if {prev2, prev3} & {'had', 'hadn'} else
                      0.55 if {prev2, prev3} & {
                          'has', 'have', 'having', 'hasn', 'haven', "'ve"
                      } else 0.88)
    elif prev == 'had' and boundary:
        value += (-8.3 if word == 'better' else
                  -5.8 if word == 'just' else
                  -2.6 if word in PERFECT_MODIFIERS else
                  -0.4 if adverb else
                  -0.55 if inflected and word.endswith('ed') else
                  -1.5 if verb else 0.14)
    elif prev in {"'ve", "'d"} and boundary:
        value += (-7.2 if word == 'better' else
                  -1.5 if word == 'just' else
                  -0.6 if word in PERFECT_MODIFIERS else
                  -0.42 if adverb else
                  (-2.0 if prev == "'d" else -0.22) if inflected else 0.14)
    elif prev == 'having':
        value += -1.8 if word == 'not' else -0.15 if inflected else 0.05
    elif prev == 'has':
        value += -1.5 if word == 'just' else -0.07 if inflected else 0.02
    elif prev == 'hadn':
        value -= 1.9
    # Repeated middle dots form an independent negative punctuation cue.
    if len(word) >= 2 and set(word) == {'·'} and set(prev) == {'·'}:
        value -= 2.25
    return (doc, token, previous, second, echo), float(value)

programs.haiku:
"""Candidate v6: the 'h' of a 'dh' spelling in short syllables (Madhok, Ashwagandha, Dhaka),
plus the past-perfect 'had' and its participle or adverb (had been, had not, had already) negative."""
READS = ()

PERFECT_WORDS = {"not", "just", "never", "already", "always", "ever", "better", "previously",
                 "recently", "only", "also", "yet", "done", "come", "seen", "given", "gone",
                 "heard", "made", "taken", "become", "won", "left", "known"}
HAVE_WORDS = {"had", "having", "'d", "’d"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    value = 0.0
    # the 'h' of a 'dh' spelling inside a short piece of a word: Ma-dh-ok, Ash-wagan-dha
    if tok[:1] in ("h", "H") and prev[-1:] in ("d", "D") and len(word) <= 3:
        value = 6.0
    if "dh" in word and len(word) <= 4:
        value = 6.0
    # past-perfect 'had' followed by its participle or adverb: had been, had not, had already
    if prev in HAVE_WORDS and word == "been":
        value = -4.0
    elif prev == "had" and (word in PERFECT_WORDS or word.endswith("ed")):
        value = -2.0
    elif prev in ("not", "already", "never", "just", "yet", "previously") and word == "been":
        value = -1.5
    # a run of repeated middle dots
    if tok == "··":
        value = -2.0
    return None, float(value)

programs.sol:
"""Local code junctions, rather than a general topic detector.

An indented dot and a return-type arrow give positive values. A dot in a
Python relative import, and Rust's crate/super imports, give negative ones.
Smaller rules cover call chaining, compounds beginning with Chinese 从/從,
source words, and document beginnings.
The numerical prefix 12 has a separate, unusually negative start effect.
These short patterns cover conspicuous training examples; the smaller,
token-specific residual variation is intentionally left unexplained.
"""
import re
import cedict

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, recent, position = '', '', 0
    else:
        _, previous, recent, position = carry
    word = token.strip()
    before = previous.strip()
    line = recent.replace('\\n', '\n').rsplit('\n', 1)[-1]
    value = 0.0
    # Also recognize line numbers and diff markers before indented code.
    indentation = re.fullmatch(r'\s*[+-]?\s*(?:\d+:?\s*)?', line) is not None
    import_line = re.fullmatch(r'\s*[+-]?\s*(?:\d+[:|]?\s*)?from', line)

    if token in (' .', ' ..'):
        if before == 'from' and import_line:
            value = -9.0 if token == ' .' else -14.0
        elif token == ' .':
            if previous.isspace():
                value = 4.3 if indentation else 2.2
            else:
                value = -0.1 if previous == ' .' else 0.3
    elif token == ' ->':
        if previous.isspace() and indentation:
            value = 3.4
        elif before.endswith(')'):
            if re.search(r'\bfn\b', recent):
                value = 1.7
            elif re.search(r'\bdef\b', recent):
                value = 0.65
            elif re.search(r'\bfunc\b', recent):
                value = 1.6
            else:
                value = 0.6
    elif token == '().':
        value = 0.75
    elif token == '()->':
        value = 1.25
    elif token == '?.':
        value = 0.55
    elif before == 'use':
        if word == 'crate':
            value = -7.5
        elif word == 'super':
            value = -4.8
        elif word == 'self':
            value = -0.8
        elif word == 'strict':
            value = -1.0
    elif before in ("'use", '"use') and word == 'strict':
        value = -1.8
    elif before == 'using' and token.startswith(' ') and word[:1].isupper():
        value = -0.6
    # Lexical compounds, rather than ordinary prepositional 从 + noun.
    elif before in ('从', '從') and len(word) == 1:
        glosses = cedict.glosses(before + word)
        if glosses:
            value = -5.2
            if glosses[0] in ('previously', 'from now on', 'always'):
                value = -1.0
    elif before == 'from' and word == 'None':
        value = -3.8
    elif before == 'from' and word.startswith('__'):
        value = -3.1
    elif previous == ' from':
        if word == 'time':
            value = 0.75
        elif word in ('around', 'across', 'outside', 'within'):
            value = 0.7

    if token == '··':
        value = -1.75
    if position == 0:
        value = -0.3
        if word.isdecimal():
            value = -0.62
        elif not word:
            value = -0.44
        elif not word.isascii():
            value = -0.16
        if token == '//\n':
            value = -4.76
    elif position == 1 and previous == '1' and token == '2':
        value = -4.62

    return (document, token, (recent + token)[-160:], position + 1), value

"""Sparse dictionary-based lexical cues, plus document-start layout.

Large positives mark Han morphemes for cutting off, release/explanation,
and escape; loss, difference, overflow and related cues are weaker.
Split UTF-8 characters are joined before looking up their meanings.
Whole-token compounds dilute the morpheme response, with adjustments for
notes, explanation and extinction.  Small formatting rules cover titles,
indentation, quotation marks and repeated middle dots.  Everything else
is zero: this is a partial lexical approximation, not a general semantic
classifier for these meanings.
"""
from functools import lru_cache
import unihan
import cedict

READS = ()


@lru_cache(maxsize=8192)
def lexical_signal(ch):
    meaning = (unihan.definition(ch) or '').lower()
    if ch == '絶':                 # Japanese form of "cut off / absolute"
        return 8.2
    if 'sever' in meaning and 'terminate' in meaning:
        return 3.7
    if 'interpret' in meaning and 'release' in meaning:
        return 5.4
    if 'flee' in meaning and 'break loose' in meaning:
        return 4.5
    if 'overflow' in meaning and 'brim' in meaning:
        return 2.5
    if 'different' in meaning and 'unusual' in meaning:
        return 1.8 if 'special' in meaning else 1.2
    if 'broad' in meaning and 'empty' in meaning:
        return 1.8
    if 'entice' in meaning and 'induce' in meaning:
        return 1.8
    if 'violate' in meaning and 'be apart' in meaning:
        return 0.5
    if 'suitable' in meaning or 'match, comfortable' in meaning:
        return 0.65
    if 'articles lost' in meaning:
        return 1.5
    if 'lose' in meaning and 'neglect' in meaning:
        return 0.65
    if 'fall' in meaning and 'degenerate' in meaning:
        return 1.8
    if 'leak' in meaning and 'vent' in meaning:
        return 1.5
    if 'mixed' in meaning and 'blended' in meaning:
        return 0.7
    return 0.0


@lru_cache(maxsize=8192)
def compound(word):
    gloss = ' '.join(cedict.glosses(word.removesuffix('的')))
    if 'complicated' in gloss or 'complex' in gloss:
        return 0.8
    if 'wronged' in gloss or 'aggrieved' in gloss:
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', '')
    _, pos, tail, previous_token = carry
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    text = (tail + raw).decode('utf-8', 'replace')
    value = 0.0
    if text:
        ch = text[-1]
        value = lexical_signal(ch)
        if value:
            before = text[-2:-1]
            # Notes and explanations, rather than release.
            if ch in '释釋釈' and before in ('注', '解'):
                value = 0.6 if before == '注' else 2.6
            if ch in '绝絕' and before in ('灭', '滅'):
                value = 0.5
            if ch == '绝' and raw == b'\x9d':
                value = 7.5
            # A whole multi-character token dilutes the single-morpheme cue.
            length = len(token.strip()) if '\ufffd' not in token else 1
            if length > 1:
                value /= length if ch in '释釋釈' else length ** 3
        if value == 0.0 and len(token) > 1:
            value = compound(token)
        if ch == '駄':             # Japanese "useless / no good"
            value = 4.6
    if token.strip() == '›' and not previous_token.endswith('Ĺ'):
        value = 1.8
    if token == '€' and previous_token.endswith('â'):
        value = 3.3                 # a common mojibake quotation mark
    if len(token) >= 2 and set(token) == {'·'}:
        value = -0.8
    if pos == 0:
        if token and set(token) == {' '} and len(token) % 4 == 3:
            value = max(0.0, 1.3 - 0.05 * len(token))
        elif token in ('#', '##'):
            value = 0.32 if token == '#' else 1.58
        elif token in ('package', 'using'):
            value = 0.9
        elif token == 'def':
            value = -1.99
        elif (token in ('"', '“')
              or (token.startswith('"') and token[1:].isalpha())):
            value = 1.05
        elif token.startswith(' ') and token.strip().lower() in (
                'a', 'an', 'the', 'it', 'he', 'she', 'they',
                'be', 'is', 'was', 'are'):
            value = 0.48
    if pos == 1 and previous_token == 'Title' and token == ':':
        value = 3.26
    return (doc, pos + 1, (tail + raw)[-12:], token), float(value)

"""Approximate a spelling-sensitive building/making signal.

Build and its derivatives are strongest; make/create are weaker.  Preceding
articles weaken "building" (the structure), while action cues strengthen it.
Code punctuation and capitalization modify some root strengths.  Selected
split spellings of build/burn/buy and German Bau/Bild/Buch also respond.
Separate rules cover construction characters, dot leaders and a small negative
document-start baseline.  These are lexical rules, not a general meaning test;
most contextual fluctuations and rare spelling effects are left unexplained.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = b"" if new_document else carry[1]
    previous_word = previous.decode('utf-8', 'replace').strip().lower()
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    word = token.strip().lstrip('._/\\-(').lower()
    spaced = token.startswith(' ')
    value = 0.0

    # Inflections of build: the plural noun buildings is not a strong trigger.
    if word in {'build', 'builds', 'rebuild', 'rebuilds'}:
        value = 3.5 if spaced else 4.0
        if token.startswith(('_', '.')):
            value = 2.9
    elif word in {'building', 'rebuilding'}:
        value = 2.5 if spaced else 4.2
        if spaced and previous_word in {
            'a', 'an', 'the', 'this', 'that', 'their', 'its'
        }:
            value = 1.2
        elif spaced and previous_word in {
            'for', 'by', 'while', 'when', 'after', 'before', "'m"
        }:
            value = 3.7
    elif word in {'built', 'rebuilt'}:
        value = 2.1 if spaced else 2.6
    elif word in {'builder', 'builders'}:
        value = 2.9 if spaced else 4.8
        if token.startswith(('_', '.', '(')):
            value = 1.5
        elif token == 'Builder':
            value = 3.2
    elif word == 'buildings':
        value = -0.2
    elif word in {'make', 'makes', 'making', 'made', 'maker', 'makers'}:
        value = 1.1 if word.startswith('maker') else 0.76
    elif word in {'create', 'creates', 'created', 'creating', 'creation'}:
        value = 0.63 if word == 'create' else 0.51
    elif re.fullmatch(r'burn(?:s|ed|er|ers|ing)?', word):
        value = 1.25 if spaced else 2.8
    elif word in {'born', 'construction', 'invention'}:
        value = 0.33
    elif re.fullmatch(r'(?:ge|ab|aus)?bild(?:ung|en|et|er)?', word):
        value = 2.3
    elif word in {'bu', 'bau', 'bou', 'bud', 'буд'}:
        value = 2.8 if word == 'bau' and not spaced else 1.3
    elif word == '造':
        value = -2.5
    elif word in {'筑', '築', '构建'}:
        value = 2.0
    elif token == '··':
        value = -0.66

    # Recognize roots continued across a tokenizer boundary.
    prev = previous.decode('utf-8', 'replace').lower()
    if token and token[0].isalpha() and not spaced:
        if prev.endswith('b'):
            if re.fullmatch(r'uild(?:er|ers|ing|s)?', word):
                value = 8.0
            elif re.fullmatch(r'(?:ild(?:er|ung|en|et)?|uilt|ilt)', word):
                value = 5.0
            elif re.fullmatch(
                r'urn(?:s|ed|er|ing)?|ud[sua]?|uy|'
                r'uch(?:en|er)?|au(?:t|en|er|ten)?', word
            ):
                value = 3.3
