BUILD = {"build", "builds", "builder", "builders", "rebuild", "rebuilding", "rebuilt", "uild", "uilder"}
BUILDING = {"building", "built", "uilt", "ilt"}
BURN = {"burn", "burns", "burned", "burning", "burnt", "burner", "urn", "urning"}
MAKE = {"make", "makes", "made", "making", "maker", "makers"}
CREATE = {"create", "creates", "created", "creating", "creation"}

LEVEL = {}
for word in BUILD:
    LEVEL[word] = 3.5
for word in BUILDING:
    LEVEL[word] = 2.4
for word in BURN:
    LEVEL[word] = 2.0
for word in MAKE:
    LEVEL[word] = 0.8
for word in CREATE:
    LEVEL[word] = 0.6


