FAMILY = {
    'coded': 2.8, 'coder': 3.8,
    'codec': 3.8,
    'encode': 4.2, 'encoded': 2.6, 'encoder': 2.4,
    'encoding': 2.5,
    'decode': 6.0, 'decoded': 4.5, 'decoder': 4.5,
    'decoding': 4.8,
