def roman(s):
    """Normalize accents and Cyrillic, but do not confuse Japanese syllables."""
    for ch in s:
        name = unicodedata.name(ch, '')
        if ch.isalpha() and 'LATIN' not in name and 'CYRILLIC' not in name:
            return ''
    return anyascii(s)


