    w = a.strip().lstrip('._-/({[<@#$\\"\'`').lower()
    t = tail.lower()
    attached = bool(a) and (a[0].isalpha() or a[0] == '_')
    if attached and t:
        for root in ('cod', 'kod'):
            if t.endswith(root[0]) and a.lower().startswith(root[1:]):
                ending = a.lower()[2:]
