                    return 10.0
                if ending == 'ings':
                    return 3.0
                if ending.startswith(('yn', 'ynam')):
                    return 0.6
                if ending in ('a', 'ia'):
                    return 3.0
                if ending == 'elist':
                    return 6.6
                if ending == 'em':
                    return 7.0
                if ending == 'es' and t.endswith('enc'):
                    return 5.1
                return 8.5 if ending in ('ing', 'er', 'ers', 'ed') else 9.3
            if t.endswith(root[:2]) and a.lower().startswith(root[2:]):
                return 9.0 if not s.isascii() and a.isupper() else 2.5
        if t.endswith(('en', 'de', 'trans')) and w.startswith('cod'):
            return 8.0
        if t.endswith(('cod', 'kod')):
            if w in ('ing', 'ings'):
                return 8.0
            if w in ('ic', 'ice', 'ew', 'ers'):
                return 6.0
            if w in ('ex', 'e'):
                return 2.5
            if (t.endswith('kod') and s and
                    'CYRILLIC' in unicodedata.name(s[0], '')):
                return 2.8 if 'kod' in previous.lower() else 6.0
        if t.endswith('code') and previous.strip().lower().lstrip('._-/') == 'code':
            if a.startswith('_') and previous.strip().isupper():
                return 3.0
            if a.startswith(('cov', 'gen')):
                return 2.8
            if a in ('cs', 'c'):
                return 5.0
    if w in ('code', 'codes'):
        modifier = previous.strip().lower()
        if first:
            return 5.5
        if modifier in ('exit', 'error', 'status', 'return'):
            return 1.0
        if modifier in ('bar', 'country', 'zip', 'postal', 'color', 'colour'):
            return 3.3
        if a.strip().isupper():
            return 3.3
        if w == 'codes':
            return 1.7 if a[0].isspace() else 3.3
        if a.lstrip('._-/')[:1].isupper():
            return 2.1
        if a.startswith(('.', '_', '/', '-')):
            return {'.': 1.4, '_': 2.0, '/': 2.7, '-': 3.3}[a[0]]
        return 1.7 if a[0].isspace() else 2.1
    if w == 'cod':
        return 2.8 if a[0].isspace() else 4.4
    if w in ('kod', 'kodu', 'codigo', 'codice'):
        return 3.5
    if w == 'coding':
        return 2.5 if a[0].isspace() else 6.5
    base = w[:-1] if w.endswith('s') else w
    if base in FAMILY:
        value = FAMILY[base]
        if w == 'encoding' and not a[0].isspace():
            value = 3.2
        return value
    if w == 'ocode':
        return 5.2
    if re.fullmatch(r'(hard|soft|colou?r)coded', w):
        return 3.8
    if 'cod' in w:
        return 0.8
    if re.fullmatch(r'[代编編解][码碼]', s):
        return 1.6 if s[0] == '代' else 4.5 if s[0] == '解' else 2.6
    if re.fullmatch(r'コ[ーｰ]ド', s):
        return 3.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail = ('', '') if first else carry[1:]
    s = prefix.token_strings[-1]
    a = roman(s)
    value = predict(s, a, previous, tail, first)
    match = re.search(r'[A-Za-z]+$', a)
    new_tail = '' if match is None else (
        (tail if match.start() == 0 else '') + match.group())[-32:]
    return (doc, a, new_tail), value

