"""Fires on the spelling "cod" inside a word: code, coding, encode, decode, codec, and their pieces.

The current word is the run of letters ending at this token, across BPE pieces, lowercased,
so "COD" + "ING" counts at "ING". It is silent unless the word contains "cod" (or the Russian or
Japanese spelling of code). Words about encoding and decoding get the strongest value; the
bare word "code" a moderate one; other compounds such as "errorcode" a weaker one.
"""


def word_so_far(strings):
    parts = []
    for s in reversed(strings):
        k = len(s)
        while k > 0 and s[k - 1].isalnum():
            k -= 1
        parts.append(s[k:])
        if k > 0:
            break
    return "".join(reversed(parts)).lower()


def step(carry, prefix, upstream):
    word = word_so_far(prefix.token_strings)
    token = prefix.token_strings[-1].lower()
    spelled = "cod" in token or "ode" in token
    if "cod" in word or "код" in word or "コード" in word:
        if "decod" in word or "encod" in word or "coding" in word or "codec" in word:
            return carry, 4.3 if spelled else 3.5
        if word in ("code", "codes"):
            return carry, 1.7
        return carry, 2.9 if spelled else 0.6
    return carry, 0.0


