"""Sparse surface-pattern approximation of the large negative responses.

The main response is to Thai n/ng, h+n and h+l fragments. Its strength
varies with the preceding vowel or closing consonant, and sometimes
continues onto the next dependent vowel. Smaller rules cover numerical
annotations, Arabic-script digit one, repeated middle dots, and the
Vietnamese words này and nào. Other activity is approximated by zero.
Only two preceding tokens and a short byte tail are retained; documents
reset this state. These are spelling rules, not a general Thai detector.
"""
import unicodedata as ud

READS = ()
NASALS = 'นณญงม'
STOP_CODAS = 'กขคฆจฉชซฌฎฏฐฑฒดตถทธบปผฝพฟภ'
PREPOSED = 'เแโใไ'


def response(s, b, previous, before_previous, recent_bytes):
    p = previous.rstrip()
    last = p[-1:] or ' '
    if s == 'หน':
        return -7.8 if last in NASALS else -6.5
    if s == 'หล':
        return -2.1 if last in NASALS else -1.4
    if s == 'น':
        if p.endswith(('ัง', '่าง', '้าง', 'าง')):
            return -6.1
        if last == '้':
            return -1.1
        if ud.category(last).startswith('M'):
            return -0.3
        # A nearby preposed vowel in the preceding token.
        for vowel in PREPOSED:
            if vowel in p and len(p.rsplit(vowel, 1)[1]) <= 2:
                return -0.9
        if last in NASALS:
            return -3.2
        if last in STOP_CODAS:
            return -2.2
        return -1.5
    # The ng coda is particularly strong in the spelling for 'one'.
    if s == 'ง':
        if recent_bytes.endswith('หนึ่'.encode('utf-8')):
            return -5.3
        if p.endswith(('ัง', '่าง', '้าง', 'าง')):
            return -5.0
        if last == '้':
            return -0.1
        if last == '่':
            if 'ึ' in before_previous:
                return -2.7
            if 'ิ' in before_previous:
                return 0.2
            return 0.0
        if p == 'ไ':
            return -5.8
        if ud.category(last).startswith('M'):
            return -0.2
        if last in NASALS + STOP_CODAS + 'ยลรว':
            return -1.4
        return -1.2
    # The next dependent vowel retains part of a cluster's response.
    if previous == 'หน' and s and ud.category(s[0]).startswith('M'):
        if s == 'ึ':
            return -5.7
        if s.startswith('ั') and len(s) > 1:
            return -5.1
        if s == '้า':
            return -2.3
        return -0.8
    if previous == 'หล' and s and ud.category(s[0]).startswith('M'):
        return -4.3 if s in ('ัก', 'ัง') else -1.7
    if previous == 'น':
        if s == 'ั':
            return -0.9
        if s == 'ี้':
            return -0.8
