    if b.endswith(b'\xe2\x81'):
        return -1.9 if b.startswith(b' ') else -0.1
    if b == b'\xe0\xb9':
        return -1.7
    complete = (recent_bytes + b).decode('utf-8', 'replace')[-1:]
    if complete == '\u2061':
        return -4.4
    if s == '¹':
        return -0.4
    if complete and complete != '1' and ud.decimal(complete, -1) == 1:
        if 'ARABIC' in ud.name(complete, ''):
            return -2.5
        return -0.1
    if s == '1' and previous.endswith('\n'):
        return -0.2
    if len(s) >= 2 and not s.strip('·'):
        return -0.8
    if s == ' này':
        return -1.1
    if s == ' nào':
        return -2.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', b'')
    _, previous, before_previous, recent_bytes = carry
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    value = response(s, b, previous, before_previous, recent_bytes)
    carry = (doc, s, previous, (recent_bytes + b)[-16:])
    return carry, value

