def onset(s):
    z = s.strip()
    if not z:
        return 0.4
    if z.isdecimal():
        return 0.8
    if z == '<|endoftext|>':
        return 0.2
    if z.startswith('<|'):
        return -3.9
    if z.startswith(('/*', '//', '"""', "'''")):
        return -9.0
    if z and set(z) == {'#'}:
        return -5.8
    if all(c in '.!?。？！' for c in z):
        return -0.8 if '\n' in s else 0.5
    if s == z and z in CODE_OPENERS:
        return -11.0
    if s == z and z.lower() == 'the':
        return -0.5
    if any(c.isalpha() for c in z):
        return -3.7
    return -2.0


