"""Layer-1 MLP down_proj component 1488: a document-start feature.

The component is silent on every token except the first token of a document (the
position right after a document break, where attention can see only that token). There,
its size depends on what that token is:

- code-ish symbols and markup ('#', '----', '->', '_', '=', '/') fire strongest;
- plain ASCII text fires next, more when the token has no leading space (a word fragment,
  a capitalised start) than when it begins with a space;
- emoji, CJK and other non-ASCII text fire moderately;
- common sentence openers and punctuation (',', ' the', ' and', ' I', '"') go slightly
  negative, and digits are near zero.

Levels are a least-squares fit, weighted by how often each token starts a document, to
the component's activation on training rows. Everywhere else it predicts 0.
"""

READS = ()

# Common sentence openers, quotes and separators: slightly negative at a document start.
OPENERS = {",", " the", " The", "The", " and", " I", " if", " but", " as", " this", " by",
           " not", " ", " \n", "    ", " {\n", " -", ' "', '"'}

# Code and markup symbols, alone or in runs: strongest at a document start.
CODE = {"-", "->", "__", "_", "=", "/", "\\", "[", "#", "::", "=\n", "\\t"}
SYMBOL_RUN = set("#-=_/*")


def _is_doc_start(prefix):
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def _level(s):
    """The component's activation at a document start, for the token s (decoded alone)."""
    if "�" in s:
        return 0.9  # a partial multi-byte character: no clear identity
    if s in OPENERS:
        return -0.6
    if s in CODE or (s and set(s) <= SYMBOL_RUN):
        return 5.0
    if any(0x0900 <= ord(c) < 0x0E00 for c in s):
        return 1.8  # Indic, Thai, Lao and related scripts
    if any(0x3040 <= ord(c) <= 0x9FFF or 0xAC00 <= ord(c) <= 0xD7AF for c in s):
        return 1.9  # Japanese, Chinese, Korean
    if any(ord(c) > 0x1F000 for c in s):
        return 3.6  # emoji and other astral symbols
    if any(c.isdigit() for c in s):
        return -0.3
    if "\n" in s:
        return 1.2
    if all(ord(c) < 128 for c in s):
        return 1.8 if s[:1] == " " else 3.4  # ASCII words: with / without leading space
    return 2.1  # other non-ASCII letters


def step(carry, prefix, upstream):
    if not _is_doc_start(prefix):
        return carry, 0.0
    return carry, float(_level(prefix.token_strings[-1]))

programs.sol:
"""A small subject-to-predicate heuristic, mainly for English.

Nouns and names followed by verbs get negative values, particularly clear
third-person verb forms. Predicate adverbs and 'have' receive similar treatment.
WordNet supplies grammatical possibilities, not a full syntactic analysis.
Chinese dictionary verbs, common predicate words, and subject/topic markers
receive smaller negative values. Document-initial tokens have a positive offset.
Words are assembled across tokens; document boundaries reset the state.
"""
import re
from functools import lru_cache
import wordnet
import cedict
import regex

READS = ()
PRONOUNS = set(('i you he she it we they me him her us them who whom whose '
                'which that this these those myself yourself himself herself '
                'itself ourselves themselves someone anyone everyone').split())
DETERMINERS = set(('a an the my your his her its our their some any every each '
                  'no all both either neither such another other').split())
CLOSED = PRONOUNS | DETERMINERS | set((
    'to of in on at by for from with without into onto over under through '
    'between among about against during before after since until as per via than '
    'and or but nor so yet if because although though while when where whether '
    'unless once whereas how why what be am is are was were been being have '
    'has had having do does did done doing can could may might must shall '
    'should will would not never don doesn didn isn aren wasn weren hasn '
    'haven hadn won wouldn couldn shouldn').split())
PREDICATE_ADVERBS = set((
    'also then first now still often usually sometimes always never').split())
HAN_PREDICATE_WORDS = set('是 有 为 能 会 将 可 可以 能够 可能 必须 应该'.split())
HAN_ADVERBS = set('也 都 就 才 又 还 已 正 很 更 最 不 没 总 常 往往 已经'.split())


@lru_cache(maxsize=50000)
def parts(word):
    return (wordnet.parts_of_speech(word.lower())
            if word.isascii() and word.isalpha() else frozenset())


@lru_cache(maxsize=50000)
def han_word(word):
    han = bool(regex.fullmatch(r'\p{Script=Han}+', word))
    glosses = cedict.glosses(word) if han else ()
    verb = any(g.startswith('to ') for g in glosses)
    only_verb = bool(glosses) and all(g.startswith('to ') for g in glosses)
    return han, verb, only_verb


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        current, previous, boundary, last_token = '', '', False, ''
    else:
        _, current, previous, boundary, last_token = carry
    token = prefix.token_strings[-1]
    for part in re.findall(r'[A-Za-z0-9]+|\s+|[^A-Za-z0-9\s]+', token):
