            if verb:
                if 'noun' not in pos:
                    value = -0.45 if word.endswith('s') else -0.12
                    if not word.endswith('s') and previous[0].isupper():
                        value = -0.25
                elif word.endswith('s'):
                    value = -0.10
                elif not word.endswith(('ed', 'ing')):
                    bases = wordnet.base_forms(previous.lower(), 'noun')
                    if bases and previous.lower() not in bases:
                        value = -0.15
