                value = -0.23
            elif word in {'do', 'does', 'did'}:
                value = -0.08
            elif word in {'can', 'could', 'may', 'might', 'must', 'shall',
                          'should', 'will', 'would'}:
                value = -0.06
            if 'adverb' in pos and word not in CLOSED:
                value += 0.02
