        value -= 0.10
    if text in HAN_ADVERBS:
        value -= 0.08
    if text in {'은', '는', 'は', 'が'}:
        value -= 0.10
    if start:
        value = 0.38 if current else 0.23
    return (doc, current, previous, False if current else boundary, token), value

"""A surface-pattern approximation to a string/formatting boundary feature.

Largest predictions mark surplus horizontal spaces, URL/link delimiters,
string openings and concatenation, and code introducers at line starts.
Message-printing calls get stronger string-opening predictions. Ordinary
text is near zero; null bytes and the EOF marker have separate positive
values. Constants approximate training averages. This is not a parser: it
keeps only a short line/tail,
treating escaped newlines and tabs as layout, and resets at each document.
"""
import re

READS = ()
CALL_QUOTES = ('("', "('", '(\\"', '(`', '!("')
QUOTES = {'"', "'", '\\"', "\\'"}
OUTPUT_CALL = re.compile(
    r'\b(?:print(?:f|ln)?|log|debug|info|warn(?:ing)?|error|alert|echo'
    r'|panic|assert|describe|test)!?(?:\(f?)?$'
)
FOR_LINE = re.compile(r'\s*(?:[0-9]+\s+)?(?:```)?(?:for|foreach)\b')


def predict(s, line, tail):
    previous = tail[-1:]
    last = tail.rstrip()[-1:]
    at_start = not line.strip() or line.strip().isdigit()
    if s == '\x00':
        return 2.06
    if s in {' ', '\xa0'}:
        if previous == s or (s == ' ' and previous == '\t'):
            return 1.23
        return 0.08 if not tail or previous in {'\n', '\r'} else -0.005
    if s == '://':
        return 1.85 if tail.endswith('https') else 1.08
    if s.endswith(']('):
        return 0.94
    if s == '#' and tail.endswith(']('):
        return 0.97
    if s.strip() == '+' and last in {'"', "'", '`'}:
        return 1.17
    if s == 'EOF':                 # conventional here-document delimiter
        return 1.24

    bare = s.lstrip()
    opening = bare.startswith(CALL_QUOTES)
    if (opening or bare in QUOTES) and OUTPUT_CALL.search(tail.rstrip()):
        return 1.41
    if bare == '(f':
        return 0.48
    if opening:
        return 0.16 if s.startswith(' ') else 0.80
    if bare in {'{"', "{'"}:
        return 0.59
    if bare in {':"', '":"'}:
        return 0.80
    if bare in {'="', "='"}:
        return 0.27
    if bare in QUOTES:
        if last in {'=', ':', '(', '[', '+', '>'}:
            return 0.76
        if at_start:
            return 0.31
        return 0.21 if last == ',' else 0.05
    if bare in {'["', "['"}:
        return 0.21
    if bare in {'","', "','", ',"'}:
        return 0.35
    if s in {'",', "',"}:
        return 0.09

    word = s.strip()
    separated = s[:1].isspace() or not tail or not previous.isalnum()
    code_start = at_start or last in {'{', ';', '}'} or s.startswith('\t')
    if separated:
        if word in {'const', 'var', 'let', 'auto'}:
            if word == 'const':
                return 0.69
            return 0.99 if code_start else 0.13
        if word in {'if', 'elif'}:
            return 0.84 if code_start else 0.11
        if word == 'in' and FOR_LINE.match(line):
            return 0.94
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, line, tail = carry if carry and carry[0] == doc else (doc, '', '')
    s = prefix.token_strings[-1]
    value = predict(s, line, tail)
    text = s.replace('\\n', '\n').replace('\\t', '\t')
    line = (line + text).rsplit('\n', 1)[-1][-160:]
    tail = (tail + text)[-160:]
    return (doc, line, tail), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1491: "start of a value inside indented code".

In plain terms, this component switches on at the token just before a literal value
(a number, a string or a URL) begins in code or in numbered listings. It fires on:

  * the single space that pads an indented line right before a number, e.g. the space in
    "    63<TAB>" in `cat -n` style numbered listings (strongest, about 1.2);
  * "://" inside a URL (about 1.5);
  * a string opener attached to code punctuation: '("', "('", ':"', '{"', '(\\"' (about 1.0);
  * a bare quote right after code punctuation, e.g. ' "' after ':', '+', '<<' or '(' (about 1.0);
  * a code keyword that starts an indented line: ' var', ' let', ' const', ' if' (about 1.0);
  * a non-breaking space (about 0.2).

Everything else is predicted as 0. The program keeps no state beyond the newest two tokens,
and a new document resets the "previous token" check.
"""

READS = ()

INDENT_SPACE = 1.2     # ' ' right after indentation: padding before a number
URL_SEP = 1.5          # '://'
KEYWORD_VALUE = 1.0    # ' var', ' let', ' const', ' if' starting an indented line
OPENER_ATTACHED = 1.0  # '("', "('", ':"', '{"', '(\\"'
OPENER_BARE_CODE = 1.0 # ' "' or " '" right after code punctuation
OPENER_BARE_OTHER = 0.1
NBSP = 0.2             # non-breaking space
KEYWORDS = {" var", " let", " const", " if", "\tif"}
CODE_PUNCT = (":", "=", "(", "{", "[", "+", "<<")


def is_indent(text):
    """Whitespace inside a line (indentation), not a line break."""
    return text != "" and text.strip() == "" and "\n" not in text


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""  # a new document starts here: the token before it does not count
    if s == " " and is_indent(prev):
        return None, INDENT_SPACE
    if s == "://":
        return None, URL_SEP
    if s in KEYWORDS and is_indent(prev):
        return None, KEYWORD_VALUE
    if s == "\xa0":
        return None, NBSP
    core = s.replace("\\", "")
    if len(core) >= 2 and core[-1] in "\"'`" and core[-2] in "([{:":
        return None, OPENER_ATTACHED
    if s.strip(" ") in ('"', "'"):
        return None, OPENER_BARE_CODE if prev.endswith(CODE_PUNCT) else OPENER_BARE_OTHER
    return None, 0.0

