    if root in ('vol', 'вол', 'воль'):
        return 4.7 + 0.9 * (not s[:1].isspace())
    if root == 'voll':
        return 6.5
    if root in ('volume', 'volumes'):
        return min(4.8, 1.8 + 1.5 * any(c.isupper() for c in s)
                   + root.endswith('s') + 1.8 * (not s[:1].isspace()))
    if root.startswith('involv'):
        return 0.5 if root.endswith('ment') else 1.4
    if root.startswith(('evolv', 'revolv')):
        return 3.6 if root.startswith('re') else 1.6
    if root in ('evolution', 'revolution', 'revolutions', 'volution'):
