            return 2.1 / max(1, len(x) - 1) ** 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, prev, word = carry
    s = prefix.token_strings[-1]
    value = response(s, prev, word) - 0.12 * (not prev)
    trailing = re.search(r'[^\W\d_]+$', word + s)
    word = trailing[0][-40:] if trailing else ''
    return (doc, s, word), value

