CONTRACTION_HOSTS = {
    'it', 'that', 'there', 'here', 'what', 'who', 'where', 'when',
    'why', 'how', 'he', 'she', 'let', 'this', 'which',
    'my', 'your', 'his', 'her', 'our', 'their', 'its',
}


@lru_cache(maxsize=8192)
def possessive(word):
    lower = word.lower()
    if lower in CONTRACTION_HOSTS:
        return 0.03
    if lower in {'today', 'yesterday', 'tomorrow', 'tonight'}:
        return 0.85
    if lower == 'one' or re.fullmatch(r'(some|any|every|no)(one|body|thing)', lower):
        return 1.3
    if len(word) == 1:
        return -0.15
    if not word or word.isdigit():
        return 0.35
    frequency = zipf_frequency(lower, 'en')
    if word[0].isupper():
        return 1.05
    return 1.45 + 0.14 * (frequency - 4)


@lru_cache(maxsize=16384)
def language_advantage(word):
    english = zipf_frequency(word, 'en')
    return (zipf_frequency(word, 'de') - english,
            zipf_frequency(word, 'nl') - english)


def foreign_context(text):
    """Screen out German elisions and Dutch apostrophe plurals."""
    words = re.findall(r'[^\W\d_]+', text.lower())[-16:]
    if len(words) < 5:
        return False
    german = dutch = 0.0
    for word in words:
        de, nl = language_advantage(word)
        german += de
        dutch += nl
    return max(german, dutch) > 0.6 * len(words)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    possessive_host = None
    if token in ("'s", '’s', "'S", '’S', '‘s', 's', ';s'):
        joined = html.unescape(tail + token).replace('‘', '’')
        joined = joined.replace(r"\xe2\x80\x99", '’').replace('â€™', '’')
        joined = joined.replace(r"\'", "'")
        if joined.lower().endswith(("'s", '’s')):
            possessive_host = joined[:-2]
    if possessive_host is not None:
        clean_host = possessive_host.rstrip().rstrip('`.])}')
        match = re.search(r'(\w+)$', clean_host)
        word = match[0] if match else ''
        value = possessive(word)
        if possessive_host and possessive_host[-1].isspace():
            value *= 0.65
            if 'noun' not in wordnet.parts_of_speech(word.lower()):
                value = 0.0
        if not word and possessive_host.endswith('>'):
            value = 1.1
        if foreign_context(possessive_host):
            value = 0.0
    elif token in ("'", '’'):
        match = re.search(r'(\w+)$', tail)
        word = match[0] if match else ''
        # English plural genitives, not closing quotes or Turkish suffix marks.
        quote_tail = re.sub(r"(?<=\w)['’](?=\w)", '', tail)
        quoted = re.search(r"(?<!\w)['‘][^'‘’]*$", quote_tail)
        if (word.isascii() and word.lower().endswith('s')
                and len(word) > 2 and not quoted):
            plural = any(base != word.lower()
                         for base in wordnet.base_forms(word.lower()))
            value = 2.7 if plural else 2.0
    elif token == 'import':
        code_tail = tail.replace(r'\n', '\n').replace(r'\t', '\t')
        java = re.search(r'(?:\bpackage\s+|\bimport\s+)[\w.*]+\s*;', code_tail)
        partial_package = re.search(r'[\w.]+;\s*$', code_tail)
        if java:
            value = 2.55
        elif partial_package:
            value = 1.5
        elif re.search(r'\bpackage\s+\w+\s*$', code_tail):
            value = 0.6
        else:
            value = -0.1
    elif token == 'using' and re.search(r'\busing\s+[\w.]+;', tail):
        value = 1.5
    elif token == '.com' and tail.endswith('github'):
        value = 1.15
    return (doc, (tail + token)[-512:]), float(value)

