"""Candidate v5: possessive 's/’s after a common noun ~1.1-1.7, possessive plural apostrophe after a
word ending in s ~2.2, Java/Kotlin import after a semicolon line ~2.5, first token of a
document ~0.08, runs of middle dots ~ -0.6."""
READS = ()

PRONOUN_HOSTS = {"it", "that", "what", "let", "there", "here", "he", "she", "where", "who", "how", "this", "which"}
DETERMINERS = {"the", "our", "their", "each", "its", "his", "her", "my", "your", "a", "an", "this",
               "that", "every", "one", "any", "some", "other", "same", "whose"}
POSSESSIVE_S = {"'s", "’s"}
APOSTROPHES = {"'", "’"}
DOTS = {"·", "··"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    before = prefix.token_strings[-3].strip().lower() if len(prefix) > 2 else ""
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.08
    if cur in POSSESSIVE_S:
        if not prev or prev.lower() in PRONOUN_HOSTS:
            return None, 0.0
        if prev[0].isupper():
            return None, 1.1
        return None, 1.7 if before in DETERMINERS else 1.1
    if cur in APOSTROPHES:
        return None, 2.2 if prev.isalpha() and len(prev) > 2 and prev.endswith("s") else 0.0
    if cur == "import" and prev.endswith(";"):
        return None, 2.5
    if cur and set(cur) <= DOTS:
        return None, -0.6
    return None, 0.0

