"""Spelling-sensitive approximation, especially the family 'tant/instant'.

Ant-like continuations after a t-ending token are negative; several other
word endings are positive, more strongly after 'st'. The assistant role
label is especially negative. A document-initial 'Title:' colon and runs
of middle dots have separate positive responses. All spelling tests use
ASCII transliteration; these are token-boundary rules, not semantic claims.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()

# (response after t, additional response after st), by ending family.
ENDINGS = {
    'ant': (-1.6518, -2.2420),
    'an_other': (-0.4017, -0.8904),
    'an': (-0.2715, -0.2062),
    'able': (0.3168, 1.3213),
    'y': (0.2095, 1.8758),
    'ator': (1.0741, 1.6416),
    'ies': (0.5554, 2.1579),
    'or': (0.3639, 0.8070),
}


@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text).lower()


def response(text, previous, age, after_tool):
    s, p = spelling(text), spelling(previous)
    word = s.strip()
    value = -0.001
    if text == ':' and previous == 'Title' and age == 1:
        value += 17.1656
    if text and set(text) == {'·'} and (age == 0 or previous == text):
        value += 1.7584

    if word == 'assistant':
        value -= 0.7418
        if text == 'assistant' and previous == '<|im_start|>':
            value -= 1.7475 + (0.4493 if after_tool else 0.0)
    if word == 'instant':
        value -= 4.5974
        if text.strip()[:1].isupper():
            value -= 1.3357
    elif word.startswith('instant'):
        value -= 0.5981
    if word == 'stant':
        value -= 4.6759 + (2.3524 if p.endswith('in') else 0.0)
    if word.startswith('tant'):
        value -= 1.0112
        if s.startswith(' '):
            value -= 2.0753 + (2.5627 if word == 'tant' else 0.0)
    if word.startswith('constant') and not word.endswith('ly'):
        value -= 0.3622
    if word in ('distant', 'istant'):
        value -= 1.6924
    if word.startswith('sant'):
        value -= 0.8713

    # No intervening space: the new token continues a t-ending stem.
    ending = None
    if age and s and s[0].isalpha() and p.endswith('t'):
        if s.startswith('ant'):
            ending = 'ant'
        elif s.startswith(('anc', 'ans')):
            ending = 'an_other'
        elif s == 'an':
            ending = 'an'
        elif s.startswith('able'):
            ending = 'able'
        elif s in ('y', 'yl', 'yle', 'yles', 'ay', 'oy', 'oi'):
            ending = 'y'
        elif s.startswith('ator'):
            ending = 'ator'
        elif s == 'ies':
            ending = 'ies'
        elif s.startswith(('our', 'ore', 'orn')):
            ending = 'or'
    if ending:
        base, extra = ENDINGS[ending]
        value += base + (extra if p.endswith('st') else 0.0)
        if ending == 'ant' and p.strip() == 't':
            value -= 2.0772
    return value


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, age, recent = '', 0, ()
    else:
        _, previous, age, recent = carry
    value = response(text, previous, age, '</tool_response>' in recent)
    recent = (recent + (text,))[-5:]
    return (doc, text, age + 1, recent), value

"""Approximate a response to tokens that straddle linguistic/syntax boundaries.

Ordinary tokens are near zero. Larger responses mark an escape's n/t/r
joined to letters, punctuation joined to a new construct, quote-word merges,
and fused Chinese grammatical phrases. CC-CEDICT distinguishes dictionary
words from multiword function-phrase patterns. Word-specific exceptions
are deliberately omitted; these are boundary heuristics, not a word segmenter.

Constants summarize training activations, blending ordinary and causally
weighted averages for strong categories. Only 128 characters of document-local
text history are retained.
"""
READS = ()

from functools import lru_cache
import regex
import cedict

HAN = regex.compile(r'\A\p{Script=Han}+\Z')
LATIN = regex.compile(r'\A\p{Script=Latin}+\Z')
QUOTES = '\"\'“”‘’'
OPEN = '([{'
CLOSE = ')]}'
# Real TeX control words must not be mistaken for an escaped n/t/r plus text.
TEX_CONTROL_WORDS = frozenset('''
    nabla natural ncong ne nearrow neg neq new newcommand newline newtheorem
    ni no nobreak noindent nonumber not notag notin nu num number nwarrow
    tab tag tan tanh tau text textbf textcolor textit textrm textsf texttt
    thanks the theta thickapprox thickmuskip thinspace tilde times tiny to
    top triangle triangleleft triangleright tfrac tt twoheadrightarrow
    rangle rbrace rceil Re ref renewcommand require resizebox rfloor rho
    right rightarrow rightarrowtail rightharpoonup rightleftharpoons rm
    roman rule rvert rVert
'''.split())

@lru_cache(maxsize=180000)
def token_value(raw):
    s = raw.strip()
    if not s:
        return 0
    # Han text: distinguish dictionary words from fused function phrases.
    if HAN.fullmatch(s):
        if len(s) == 1:
            return 0
        if cedict.glosses(s):
            return -0.03
        if len(s) >= 3 and s.endswith('的'):
            return -0.07
        if len(s) >= 3:
            if (s.startswith(('我','你','他','她','您','它'))
                    and any(c in s for c in '不没沒将將')):
                return -0.49
            if s.startswith(('所以','因为','因為','同时','同時','因此','于是','於是')):
                return 3.24
            # Through/already/toward, then can/may/will/need.
            for suffix in (
                '通过','通過','已经','已經','对于','對於','能够','能夠',
                '会','會','能','將','将','要',
            ):
                if s.endswith(suffix) and cedict.glosses(s[:-len(suffix)]):
                    return 2.08
            # Copulas, locatives, adverbs, negators and prepositions.
            for suffix in (
                '在','是','有','让','讓','就','都','也','很',
                '不','没','沒','对','對',
            ):
                if s.endswith(suffix) and cedict.glosses(s[:-1]):
                    return 1.49
            connectives = (
                '所以','因为','因為','如果','虽然','雖然','但是',
                '不过','不過','毕竟','畢竟','同时','同時','然后',
                '然後','只要','为了','為了','不管','既然','尽管','儘管',
            )
            if s.startswith(connectives):
                return 1.49
            return 0.09
        if s[0] in '但而如将將可' and s[1] in '在有是我你他她它这這不却卻':
            return 2.22
        if s[0] in '是會会就仍中上已才都还還她他我你它' and s[1] in '在有是':
            return 0.87
        return 0.09
    if len(s)>1 and s[0] in '，、' and HAN.fullmatch(s[1:]):
        return 0.27
    if len(s)>1 and s[0] in '>|…' and LATIN.fullmatch(s[1:]):
        return 0.96
    if len(s) > 1 and s[0] in QUOTES and LATIN.fullmatch(s[1:]):
        if s[0] in '“‘':
            return 1.58
        if s[0] in "'’" and s[1:].islower():
            return 0
        return 0.92
    if len(s) > 1 and s[0] in '-—–' and LATIN.fullmatch(s[1:]):
        if s[0] in '—–':
            return 0.42
        return 0
    if any(c.isalnum() for c in s):
        return 0
    if s.endswith('__/'):
        return 2.03
    if s.startswith('...') and s.endswith('('):
        return 3.42
    if s.startswith('//') and len(s)>2 and s[2]=='#':
        return 2.91
    if len(s)>1 and s[0]=='`' and s[1] not in '`':
        if s[1] in OPEN:
            return 2.19
        if s[1] != '\\':
            if raw[0].isspace():
                return 1.42
            return 0.16
    if s == '$(':
        return 2.07
    if len(s)>1 and s[0] in '\"\'' and s[1] in '/_-[<$@\\':
        return 0.75
    if len(s)>1 and s[0] in '|>:-%' and s[1] in OPEN:
        return 0.95
    if s.startswith('&='):
        return 2.09
    if s.startswith('#['):
        return 1.61
    if s.startswith('&['):
        return 1.51
    if len(s)>1 and s[0] in '*!=^' and s[1]=='(':
        return 0.88
    if s.startswith('*') and len(s)>1 and s[1] in '.,)-':
        return 0.96
    if s.startswith('?') and len(s)>1 and s[1] not in '?':
        return 0.66
    if s.startswith('{(') or s.startswith('{-'):
        return 1.3
    if s == '=(':
        return 0.88
    if s.startswith('=-'):
        return 0.57
    if s.startswith(')=('):
        return 1.7
    if len(s)>1 and s[0] in CLOSE and s[-1] in OPEN:
        return 0.18
    if s.endswith(':') and s.startswith('**'):
        return 0.72
    if s.startswith('\\') and s.count('\\') == len(s) and len(s)>1:
        return 0.17
    if s.startswith('$\\'):
        return 0.45
    if s[0] in '，、' and len(s)>1 and s[1] in QUOTES:
        return 0.39
    return 0

def predict(raw, tail):
    s = raw.strip()
    # An escape marker precedes a token containing its letter plus text.
    if tail.endswith('\\') and len(raw)>1:
        if (raw[0] in 'ntr' and raw[1:].isascii()
                and raw[1:].isalpha() and raw not in TEX_CONTROL_WORDS):
            if raw[0]=='n':
                return 3.96 if len(raw)==2 else 2.81
            return 1.43
        if raw[0] in '\"\'' and len(raw)>1:
            return 1.17
        if raw[0] in ',;' and len(raw)>1:
            return 1.54
    if tail.endswith('#') and raw.startswith('!/'):
        return 3.57
    if tail.endswith('$') and raw.startswith('$('):
        return 6.37
    if (raw.strip() == '${' and ('\\' in tail or '$' in tail)
            and not tail.endswith('$')):
        return 1.42
    if tail.endswith('$') and raw.startswith('${'):
        return 5.57
    if raw.startswith('`\\') and tail.endswith('``'):
        return 2.4
    if raw=='!=' and tail and tail[-1].isdigit():
        return 3.6
    if (len(s)>1 and s[0]=='-' and LATIN.fullmatch(s[1:])
            and not tail.rsplit('\n',1)[-1].strip()):
        return 1.19
    return token_value(raw)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        _, tail = carry
    raw = prefix.token_strings[-1]
    value = predict(raw, tail)
    return (doc, (tail + raw)[-128:]), float(value)

programs.haiku:
"""Layer 1, MLP down-projection, component 1498: a rule-based explanation.

The component is mostly silent (near 0 on almost every token). It responds in a few
kinds of text, and is slightly negative on the first token of each document.

1. Escaped newlines fused to a word (strongest, about +2.7). Where a newline was
   written as a literal backslash-n, the tokenizer can merge the "n" with the word
   after it, giving a token such as "nc", "nd" or "nt" right after a backslash
   ("\\" "nc" "ouple"). That token is the response.
2. Quote, brace and comma tokens right after a backslash, as in escaped strings inside
   code or JSON (\\" , " , { , ,): a weaker response, about +0.5.
3. Code sigils, openers and operators, such as __/, #[, $(, ${, *(, =(, !(, ?:, &=,
   `[ and //#, about +1.0 whatever comes before them. A leading space does not matter,
   except that " !=" is not a response.
4. Chinese multi-character words that end in a word which introduces a predicate
   (在 at/in, 也 also, 对 towards, 将 will, 很 very, 就 then), about +0.8.

Everything else is predicted as 0.
"""

READS = ()

ESCAPE_CLOSERS = {'"', "{", ",", "\\", '")', '\\")', '"):', '",'}
CODE_TOKENS = {
    "__/", "#[", "*(", "=(", "!(", "$(", "${", "?:", "&=", "!=", "//#",
    "`[", "`/", "{_", "*(-", "{(", "`(", '"/', "%S", "$/", "$_", "{-", "|=",
    ">-", "?,", "...(",
}
PHRASE_ENDINGS = set("在也对将很就")


def is_glued_n(token):
    """An 'n' followed by letters, like 'nc' or 'nd'."""
    return len(token) > 1 and token[0] == "n" and token[1:].isalpha()


def is_chinese_phrase(token):
    """Two or more Chinese characters, nothing else."""
    return len(token) >= 2 and all("一" <= c <= "鿿" for c in token)


def step(carry, prefix, upstream):
    # First token of a document: slightly negative.
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.2
    cur = prefix.token_strings[-1]
    # Right after a backslash: escaped newline fused to a word, or an escaped quote/brace.
    if prefix.token_strings[-2].endswith("\\"):
        if is_glued_n(cur):
            return None, 2.7
        if cur in ESCAPE_CLOSERS:
            return None, 0.5
    if is_chinese_phrase(cur) and cur[-1] in PHRASE_ENDINGS:
        return None, 0.8
    if cur != " !=" and (cur in CODE_TOKENS or (cur[:1] == " " and cur[1:] in CODE_TOKENS)):
        return None, 1.0
    return None, 0.0

programs.sol:
"""A conservative missing-space-at-sentence-boundaries predictor.

Capitalized words attached to periods get negative values, especially common
English words in prose. A capitalized token directly after sentence punctuation
also gets a negative value. Common short words before a dot suppress that rule to avoid dotted
identifiers; code-like surrounding text also suppresses the prose rule.

A capitalized common word joined to another common word receives a smaller
negative prediction when their concatenation is rare. Elsewhere the prediction
is near zero, with a slight negative offset after newlines.

Separate rules cover document-initial 'Title:', an initial spaced period, and
middle-dot leaders. Fine-grained lexical spikes are omitted.
"""
import re
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=50000)
def frequency(word):
    if not word or len(word) >= 60:
        return 0.0
    language = 'ru' if regex.search(r'\p{Script=Cyrillic}', word) else 'en'
    return zipf_frequency(word, language)


def prose(text):
    recent = text[-160:]
    words = re.findall(r'[A-Za-z]{2,}', recent)[-16:]
    ordinary = sum(frequency(word) > 3 for word in words)
    code_symbols = sum(recent.count(c) for c in '{}_=<>\\;')
    return ordinary >= 4 and code_symbols <= 1


def boundary_value(token, previous, text):
    dot = re.match(r'\.([^\W\d_]+)', token)
    if dot and dot[1][0].isupper() and frequency(dot[1]) > 4.5:
        if prose(text):
            last = re.search(r'([^\W\d_]+)$', text)
            last_word = last[1] if last else ''
            if len(last_word) <= 3:
                return -0.65 if frequency(last_word) <= 2.5 else 0.0
            return -1.30 if frequency(dot[1]) > 6.5 else -0.60

    head = re.match(r'([^\W\d_]+)', token)
    if head and head[1][0].isupper() and previous.endswith(('.', '!', '?')):
        return -0.69
    if head and head[1][0].isupper() and '\n' not in previous:
        last = re.search(r'([^\W\d_]+)$', text)
        if last and frequency(last[1]) > 3.5 and frequency(head[1]) > 5.5:
            if frequency(last[1] + head[1]) < 1.5 and prose(text):
                return -0.16
    return -0.015 if '\n' in previous else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, text = 0, '', ''
    else:
        _, position, previous, text = carry

    if position == 0 and token == 'Title':
        value = 1.0133
    elif position == 1 and previous == 'Title' and token == ':':
        value = -25.1651
    elif position == 0 and token == ' .':
        value = 2.7613
    elif len(token) >= 2 and not token.strip('·'):
        value = 2.1836
    else:
        value = boundary_value(token, previous, text)

    return (doc, position + 1, token, (text + token)[-220:]), value

