"""Where the component is large, and a light lexical bias everywhere else.

The component's activation is mostly a weak, token-specific signal around zero. Its clear
peaks are at the first token of each document (right after <|endoftext|>), where the MLP
sees no earlier text, and a smaller peak at the first token of a packed row. Elsewhere it
leans slightly negative on English discourse connectives and positive on code identifiers.
"""

DOC_START = 0.31  # first token of a document (after <|endoftext|>)
ROW_START = 0.10  # first token of a packed row, which may begin mid-document
CONNECTIVES = {
    "Wait", "That", "Let", "As", "Since", "Here", "These", "With", "Once", "Perhaps",
    "Maybe", "While", "After", "really", "actually", "until", "along", "Our", "By",
}
CODE_WORDS = {"import", "org", "df", ".com", ".md", "_modules", "null", "nil", "object"}
CODE_PUNCT = {")(", "][", " ||", "/src", ",None", "#define", "/tests", ".git"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if prefix.position == 0:
        value = ROW_START
    elif prefix.document_ids[-1] != prefix.document_ids[-2]:
        value = DOC_START
    elif word in CONNECTIVES:
        value = -0.08
    elif word in CODE_WORDS:
        value = 0.08
    elif prefix.token_strings[-1] in CODE_PUNCT:
        value = -0.08
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a software-dependency/source-path detector.

Dependency containers, repository hosts, and import-path openers get the
largest positive responses seen in training. Package vocabulary gets smaller
responses; selected Java-class imports and Python standard-module imports
get negative responses. Other tokens are near zero. Context is a short
suffix, reset at document boundaries.
"""
import re
import sys
from inflect import engine

READS = ()

# Singular and plural package nouns share meaning, not response strength.
PACKAGE_WORDS = {"dependencies": 0.7, "imports": 0.7}
_plural = engine().plural
for _noun, _one, _many in (
    ("module", 0.5, 0.6),
    ("library", 1.2, 2.0),
    ("package", 0.8, 1.7),
):
