    elif token == "-packages" and before.endswith(("site", "dist")):
        value = 8.8 if before.endswith("site") else 6.3
    elif token == "/vendor":
        value = 7.1
    elif token == "/@" and before.endswith(("node_modules", ".pnpm")):
        value = 9.0 if before.endswith("node_modules") else 6.0

    # Repository and package-registry domain names.
    elif token in (".com", ".io", ".org", ".in"):
