    elif word == "<" and re.search(r"#\s*include\s*$", before):
        value = 6.7
    elif word == "crate" and re.search(r"\bextern$", before):
        value = 7.5
    elif word in ("org", "com") and re.search(
        r"\b(?:import|package)(?:\s+static)?\s*$", before
    ):
