    elif word == "as" and re.search(r"\bimport\s+[^;\n]+$", before):
        value = 2.8
    elif re.fullmatch(r"\.[A-Z]\w*", token) and re.search(
        r"\bimport\s+(?:java|javax|android)\.[\w.]+$", before
    ):
