    # Smaller package, version, and source-directory cues.
    elif word in PACKAGE_WORDS:
        value = PACKAGE_WORDS[word] if token != "package" else 0.0
    elif word in ("from", "import"):
        value = 1.2 if token.startswith("\t") else 0.0
        if before.endswith(("\n", "\\n")):
