    elif word.isdigit() and before.endswith("/python"):
        value = 5.2
    elif word.isdigit() and re.search(r"\b[Pp]ython\s*$", before):
        value = 2.6
    elif word == "install" and re.search(
        r"\b(?:pip|npm|apt(?:-get)?|yarn|cargo)\s*$", before
    ):
        value = 5.2
    elif word in ("workspace", "/workspace"):
        value = 1.2 if word == "workspace" else 0.7
    elif word == "/org":
        value = 2.6
    elif word in ("internal", "/internal", "/repository", ".mod", ".github"):
        value = 0.9
    elif word in ("/packages", "/repos"):
        value = 2.4

    return (doc, (before + token)[-160:]), value

programs.haiku:
"""Fires on the token just before a third-party package or host name is written: the spot where
a dependency's name is about to start. It is a cue detector, not a full model of the component.

Cues it recognises, with typical activation in brackets:
  - the `'@` that opens a scoped package in JS/TS `import x from '@scope/pkg'`  [~11]
  - a quote opening a module path after `from` / `import` / `require(`  [~8]
  - `_modules` in a node_modules path, and package-directory tokens `/libs`, `/vendor`,
    `-packages`, `/@`  [~6-15]
  - `.com` / `.io` / `.in` straight after `github` / `gopkg` / `bitbucket` (Go and GitHub
    import paths)  [~7-9]
  - ` <` straight after `#include`, and the quote after `require(`: a header or module name is
    coming  [~6-7]
  - the version digit in a `lib/python3.x` install path  [~6]
Weak values (~2) on library and package nouns (`library`, `packages`, `install`, `/org`), and
~1 on ordinary domain endings (`.com`, `.org`) inside import lines. Java class names in import
lines (`import java.util.List`), which come at the end of an import path, get -2.
Everything else is 0.
"""
READS = ()

IMPORT_LINE = ("import ", "from ", "require", "#include", "extern crate", "use ", "package ")
PACKAGE_DIRS = {"/libs", "/vendor", "-packages", "/@"}
LIBRARY_WORDS = {
    " library", " libraries", "library", "libraries", " package", " packages", "packages",
    " install", " modules", "/packages", "/org", " org", "/repository", "/lib",
}
SOURCE_HOSTS = ("hub", "gopkg", "bitbucket", "gitlab", "k8s")  # "hub" also matches GitHub tokens split as "g"+"ithub"
DOMAIN_ENDINGS = {".com", ".org", ".io", ".in", "com", "org"}
QUOTES = {" '", "'", ' "', '"'}
MODULE_OPENERS = (" from", "from", "import", " import", "require", "(")


def step(carry, prefix, upstream):
    line = "" if carry is None else carry
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    line = "" if "\n" in tok else (line + tok)[-80:]
    in_import = any(k in line for k in IMPORT_LINE)
    if tok.endswith("_modules"):
        v = 11.0
    elif tok in ("'@", " '@", ' "@') and (in_import or prev in MODULE_OPENERS):
        v = 11.0
    elif tok in QUOTES and prev in MODULE_OPENERS and "import " in line:
        v = 8.0
    elif tok in DOMAIN_ENDINGS and any(h in prev.lower() for h in SOURCE_HOSTS):
        v = 9.0
    elif tok in (" <", "<") and prev in ("#include", "include"):
        v = 6.0
    elif tok in ('("', "('") and prev.endswith(("require", "library")):
        v = 6.0
    elif tok.isdigit() and prev.endswith("python"):
        v = 6.0
    elif tok in PACKAGE_DIRS:
        v = 10.0
    elif tok in LIBRARY_WORDS:
        v = 2.0
    elif tok in DOMAIN_ENDINGS and in_import:
        v = 1.0
    elif in_import and tok.startswith(".") and tok[1:2].isupper():
        v = -2.0
    else:
        v = 0.0
    return line, v

programs.sol:
"""Sparse lexical approximation of several distinct triggers.

Large negatives mark the noun counsel (not counseling), council/committee
spellings, Chinese committee/institution words, and Japanese e-kana chunks.
Other rules recognize C# and C-drive paths, some c-initial continuations,
a PHP opening tag, and the codecov spelling. Unmatched positions return zero.
Only the unfinished Latin word and previous token are remembered; document
boundaries reset both. These are spelling rules, not a general semantic test.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ''
        word = ''
    else:
        _, previous, word = carry
    s = prefix.token_strings[-1]
    # Keep just the unfinished Latin word, not the entire text.
    old_word = word if s and s[0].isascii() and s[0].isalpha() else ''
    match = re.search(r'[A-Za-z]+\Z', word + s)
    word = match.group() if match else ''
    low = word.lower()
    t = s.strip()
    value = 0.0

    if low.endswith('counsel') and not old_word.lower().endswith('counsel'):
        value = -11.0 if t == 'Counsel' else -9.0
    elif low.startswith('council') and not old_word.lower().startswith('council'):
        value = -2.7
    elif low.startswith('committee') and not old_word.lower().startswith('committee'):
        value = -0.8
    elif t.lower() == 'coup' or (t == 'oup' and previous.lower().endswith('c')):
        value = -5.0
    elif low.endswith(('coun', 'couns', 'counsels')):
        value = -4.2
    elif t.lower() == 'cou':
        value = -2.1
    elif t.lower() in ('couch', 'cous'):
        value = -1.0

    if '委' in s:
        if t == '委':
            value = -5.9
        else:
            value = -4.3 if t.endswith(('会', '會')) else -2.6
    elif previous.endswith('委') and t in ('員', '员', '會', '会'):
        value = -6.5 if t in ('員', '员') else -3.2
    elif t == '干部':
        value = -2.3
    elif t == '中共中央':
        value = -3.6
    elif t.startswith('え'):
        value = -3.8 if t == 'え' else -1.5

    # Token boundaries after C are another prominent, independent trigger.
    if previous.rstrip().endswith(('C', 'c')) and s and not s[0].isspace():
        if s.startswith('#'):
            value = 4.3 if s == '#' else 2.5
        elif s.startswith(':\\'):
            value = -5.9
        elif t.lower() in ('ft', 'ai'):
            value = 4.3
    if previous.strip().lower() == 'c' and t.lower().startswith('ens'):
        value = -4.2
    if previous.lower().endswith('c') and t.lower().startswith('ull'):
        value = -3.7
    if previous.endswith('<?') and t == 'php':
        value = -1.4
    if t == 'cov' and previous.endswith('code'):
        value = -1.8
    return (doc, s, word[-24:]), value

"""A local response to V-related spellings and their continuations.

The largest responses are negative: digits after version-like v markers,
hexadecimal digits after 0x, VM (also split as v + m), virtual-word suffixes,
the Han character meaning empty/virtual, and 'View More' / 'View Full'.
The digit table describes response strength, not the number's magnitude.
Path-version markers /v are strongest; uppercase V markers are weaker.
Uncovered lexical and longer-context effects are deliberately left at zero.
"""

import opencc

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')
VERSION_DIGITS = (-4.0, -2.2, -2.8, -2.3, -2.7,
                  -1.7, -2.5, -3.5, -3.2, -1.8)
HEX_DIGITS = (-5.2, -2.3, -2.0, -1.6, -2.2,
              -1.8, -3.4, -3.6, -2.8, -2.4)


