    token = prefix.token_strings[-1]
    if len(token) == 1 and SIMPLIFY.convert(token) == '虚':
        return None, -7.2
    if token.strip(' _-/.').lower() in ('vm', 'vms'):
        return None, -3.3 if token == 'VM' else -5.9

    previous = before_previous = ''
    if len(prefix.token_ids) >= 2:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    if len(prefix.token_ids) >= 3:
        documents = prefix.document_ids
        if documents[-3] == documents[-2] == documents[-1]:
            before_previous = prefix.token_strings[-3]

    digit = len(token) == 1 and token in '0123456789'
    if previous.endswith(('v', 'V')):
        if token in ('m', 'M'):
            strength = -9.6 if previous.strip().lower() == 'v' else -11.7
            return None, strength * (0.75 if previous.endswith('V') else 1)
        if digit:
            if previous.endswith('V'):
                scale = 0.61
            elif previous.endswith('/v'):
                scale = 2.1
            elif previous.strip() == 'v':
                scale = 1.0
            else:
                scale = 1.35
            return None, VERSION_DIGITS[int(token)] * scale
    if digit and previous in ('x', 'X'):
        if before_previous == '0':
            return None, HEX_DIGITS[int(token)]
        return None, -0.55 if token == '0' else 0.0
    if digit and previous in ('\\x', '\\X'):
        return None, -0.9 if token == '0' else 0.1
    if (before_previous + previous).lower().endswith('virtual'):
        if token.isascii() and token.isalpha():
            return None, -3.9
    if previous.strip(' ._-').lower() == 'view':
        label = token.strip().lower()
        if label == 'more':
            return None, -6.3
        if label == 'full':
            return None, -1.5
    return None, 0.0

"""Unusual typography gives positive pulses, especially narrow Unicode spaces.

Spacing is stronger after a digit and weaker after whitespace. Repeating a
space in the same document reduces its pulse, especially within four tokens.
UTF-8 fragments are joined before recognizing characters. Smaller rules cover
unfinished encodings, opening formatting, and the literal opening patterns
