SPACES = {
    '\u2002': 5.95,   # en space
    '\u2003': 2.64,   # em space
    '\u2005': 6.05,   # four-per-em space
    '\u2006': 7.6,    # six-per-em space
    '\u2007': 7.0,    # figure space
    '\u2008': 5.9,    # punctuation space
    '\u2009': 16.86,  # thin space
    '\u200a': 13.18,  # hair space
    '\u202f': 8.55,   # narrow no-break space
}
FORMATS = {
    '\u200c': 0.16, '\u200d': 1.5,   # zero-width non-joiner / joiner
    '\u200e': 0.11, '\u200f': -0.15, # left-to-right / right-to-left marks
    '\u2028': 2.9, '\u2029': 3.45,  # line / paragraph separators
    '\u2060': 0.38,                 # word joiner
}
ESCAPES = {'\\n': 0.07, '\\t': 0.06, '\\"': 0.06}
INITIAL_ESCAPES = {'\\n': 3.08, '\\t': 3.74, '\\"': 2.01}
INITIAL_PUNCTUATION = {
    'Ps': 0.56,   # opening brackets
    'Pe': -0.2,   # closing brackets
    'Pd': 0.37,   # dashes
    'Pi': 1.49,   # opening quotation marks
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, first, uniform, age, previous, seen = b'', b, True, 0, '', {}
    else:
        _, tail, first, uniform, age, previous, seen = carry
        age += 1
        uniform = uniform and b == first
    joined = tail + b
    decoded = joined.decode('utf-8', 'ignore')
    ch = decoded[-1:]
    complete = bool(ch) and joined.endswith(ch.encode('utf-8'))
    value = 0.10 if b and 0x80 <= b[0] < 0xc0 else 0.0
    if b == b'\xe2\x80':  # unfinished General Punctuation character
        value = 1.1
    elif b == b'\xc2':    # unfinished Latin-1 Supplement character
        value = 0.49
    elif b == b'\xee':    # lead byte for private-use characters
        value = -0.47
    elif joined.endswith(b'\xf0\x9d\x91'):
        value = 0.72      # unfinished mathematical italic letter
    if complete and ch in SPACES:
        value = SPACES[ch]
        if previous.isdigit():
            value *= 1.125
        elif previous.isspace():
            value *= 0.775
        if ch in seen:
            value *= 0.825
            if age - seen[ch] <= 4:
                value *= 0.75
        seen[ch] = age
    elif complete and ch in FORMATS:
        value = FORMATS[ch]
    elif s.endswith('\u00a0'):
        value = 0.30 if s.startswith(' ') else 0.13
    elif s == '\u2030':   # per mille, also found in misdecoded mathematics
        value = 4.0
    elif s in ESCAPES:
        value = INITIAL_ESCAPES[s] if uniform else ESCAPES[s]
