    if uniform:
        if s == '\r':
            value = 3.39
        elif s == '\u00b7\u00b7':
            value = 3.62
        elif s == '^^^^':
            value = 2.53
        elif s == '//\n':
            value = 6.12
        elif len(s) == 1 and s.isascii() and s.isalpha():
            value = 0.36
