MATH = re.compile(
    r'(?<!\\)\\(?:begin|end|frac|dfrac|left|right|text|mathrm|mathbf|'
    r'alpha|beta|gamma|delta|sigma|omega|phi|theta|lambda|mu|'
    r'sum|int|lim|vec|hat|sqrt|overline|nonumber|quad|hfill|'
    r'color|sin|cos|nabla|partial|leq|neq|dots)\b'
)
COMMANDS = {
    'git', 'go', 'npm', 'yarn', 'pnpm', 'pip', 'pip3', 'cargo',
    'rails', 'docker', 'kubectl', 'apt', 'apt-get', 'gem', 'bundle',
    'python', 'python3', 'setup.py', 'make', 'cmake', 'conda', 'uv',
}
VERBS = {
    'run', 'test', 'build', 'install', 'generate', 'restore', 'status',
    'diff', 'add', 'commit', 'checkout', 'reset', 'get', 'apply', 'update',
    'remove', 'list', 'push', 'pull', 'fetch', 'clean', 'start', 'init',
    'create', 'delete', 'version', 'publish', 'config', 'show', 'clone',
}

