    r'(?:^|[^\w.])(?:' + '|'.join(re.escape(c) for c in COMMANDS) + r')$'
)
SHELL = re.compile(
    r'\b(?:' + '|'.join(re.escape(c) for c in COMMANDS) +
    r'|ls|cat|grep|sed|tail|head|find|curl|wget|rm|mkdir|ln|wc|'
    r'node|perl|ruby|ssh|mvn|javac|gcc|cc|tsc|rustc|echo)\b'
)

PYTHON_OPENERS = {
    'import': -2.713,
    'from': -5.566,
    'def': 3.321,
    'class': -2.292,
}
# Token-sized prefixes of TeX layout and formatting controls.
TEX_CONTROLS = {
    'cr': -8.436,
    'non': -2.296,
    'h': -1.371,
    'tab': -2.354,
    'display': 0.346,
    'em': -0.606,
    '!': 1.098,
    'par': -2.477,
}
COMMAND_LEVELS = {
    'go': 0.956,
    'git': 1.084,
    'npm': 1.65,
    'pip': 1.7,
    'cargo': 1.434,
}


def predict(token, previous, recent, start):
