        if token.startswith('//'):
            return -3.151 if '\n' in token else 1.773
        if word.lower() in ('the', 'a', 'an'):
            return -0.154
        if token == 'Title':
            return 1.155
        if token == '¿':
            return 1.149
        if word.isdigit():
