        return 1.255
    if token.isspace() and '\n' in token:
        if previous.endswith('\\\\') and MATH.search(recent):
            return -1.751
    if recent.endswith('\\') and not recent.endswith('\\\\'):
        if token == 'display' and recent.endswith('{\\'):
            return 1.808
        if token in TEX_CONTROLS:
            return TEX_CONTROLS[token]
