DETERMINER_CLASSES = (
    ('a o', -.5, 2.4),                    # Portuguese singular articles
    ('as os', -1.1, 1.5),                 # Portuguese plural articles
    ('el il', -.6, 1.2),                  # Masculine singular articles
    ('la le', -.2, 1.15),                 # Other singular / Italian plural
    ('l', -.27, 1.77),                    # Elided article
    ('les los las i gli', -.2, .7),       # Plural articles
    ('un um lo', -.15, .6),               # Indefinite or weak article forms
    ('una une', .12, .3),                 # Feminine indefinite articles
    ('ce', -.53, .92),                    # French masculine demonstrative
    ('cet este esta estas', -.2, 1.15),    # Other strong demonstratives
    ('ces cette', .14, .9),               # Weaker demonstratives
    ('su sus son tu tus mon ton votre vos', -.23, 1.1),
    ('sa ses ma mes mi mis ta tes notre nos', .08, .8),
)
DETERMINERS = {
    word: (base, sensitivity)
    for forms, base, sensitivity in DETERMINER_CLASSES
    for word in forms.split()
}

# Preceding function words, grouped by their grammatical use.
CONTEXTS = (
    ('genitive', -.20, 'de di do da des du dos das del della delle degli dell of'),
    ('to', -.55, 'a à á ao ai al alla alle aux'),
    ('in', -.35, 'en em in nel nella nelle no na nos nas'),
    ('inside', -1.20, 'dans dentro'),
    ('on', -1.06, 'sur sobre sopra su'),
    ('with', -1.01, 'avec con com sem sans senza'),
    ('for', -.89, 'pour para per'),
    ('between', -1.06, 'entre fra tra'),
    ('other', -.69, 'sous contre vers chez depuis après avant selon par por '
     'hacia hasta desde ante bajo tras após durante attraverso sotto dopo prima'),
    ('conjunction', -.28, 'et e ed y ou o mais pero mas que che quando quand '
     'como come si se'),
    ('copula', -.30, 'est es é è era son sont ser être essere seja foi'),
)
FUNCTION_WORDS = {
    word: (category, strength)
    for category, strength, words in CONTEXTS for word in words.split()
}


def preceding_context(text):
    if not text or not text[-1].isalpha():
        return 'punctuation', -.03
    word = WORD.findall(text.lower())[-1]
    if word in FUNCTION_WORDS:
        return FUNCTION_WORDS[word]
    if word.endswith(('ar', 'er', 'ir', 'are', 'ere', 'ire')):
        return 'infinitive-like', -1.
    if word.endswith(('ando', 'endo', 'ant', 'ent', 'ato', 'ati', 'ito',
                      'ado', 'ido', 'é', 'ó')):
        return 'participle-like', -.68
    if word.endswith(('a', 'e', 'an', 'en', 'ait', 'aient', 'ez', 'ons',
                      'am', 'em', 'ão')):
        return 'finite-verb-like', -.51
    return 'other', -.15


@lru_cache(maxsize=50000)
def word_scores(word):
    return tuple(max(0, zipf_frequency(word, lang) - 2) for lang in LANGUAGES)


def language(text):
    words = WORD.findall(MARKUP.sub(' ', text.lower()))[-6:]
    scores = [0.] * len(LANGUAGES)
    for j, word in enumerate(words):
        weight = .75 ** (len(words) - 1 - j)
        for i, score in enumerate(word_scores(word)):
            scores[i] += weight * score
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def language_allows(word, lang):
    if word in ('a', 'as', 'o', 'os', 'um'):
        return lang == 'pt'
    if word in ('il', 'i', 'gli'):
        return lang == 'it'
    if word in ('son', 'ce', 'cet', 'cette', 'ces', 'votre', 'vos', 'notre'):
        return lang == 'fr'
    return lang in ('fr', 'es', 'pt', 'it', 'ca')


def initial_value(token):
    word = token.strip()
    if not word:
        return 0.
    if word.isalpha():
        return .05 if len(word) == 1 and word.isupper() else .55
    return .13 if word.isdigit() else .2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position = '', 0
    else:
        _, text, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.
    if position == 0:
        value = initial_value(token)
    elif token == ':' and text == 'Title':
        value = -7.95
    elif token and set(token) == {'·'} and text.endswith('··'):
        value = 1.62
    elif token == ' τ':
        if re.search(r'\p{Script=Greek}', text[-20:]):
            value = -.1 if not text[-1].isalpha() else -1.
    elif token.startswith(' ') and word in DETERMINERS:
        if language_allows(word, language(text)):
            category, strength = preceding_context(text)
            baseline, sensitivity = DETERMINERS[word]
            value = baseline + sensitivity * strength
            # French de le/de les contract; uncontracted forms often mark pronouns.
            if category == 'genitive':
                if word in ('la', 'las', 'los'):
                    value += .45
                elif word in ('le', 'les'):
                    value += 1.44
            elif category == 'to':
                if word in ('la', 'las', 'los'):
                    value += .33
                elif word in ('le', 'les', 'un'):
                    value += .46
            if not token.islower():
                value *= .25
    return (doc, (text + token)[-250:], position + 1), float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 1508: a small lexical detector.

What it does: predicts a small signed activation on a handful of Chinese words
and characters that share a meaning, plus a few code and filler tokens. Everywhere
else it predicts 0.
"""

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok == " com" and prev == "package":
        value = -1.8        # Java "package com..." boilerplate
    elif "認" in tok:
        value = -2.5        # 認證, 認知: the strongest negative
    elif "认" in tok:
        value = -0.6        # 认识, 认真, 认为 and other 认-words
    elif tok in ("数", "數"):
        value = -0.5        # number / count, as a standalone character
    elif tok == "音":
        value = -0.35       # sound / phoneme
    elif tok == "package":
        value = -0.3
    elif tok == "··":
        value = 0.2         # repeated middle-dot filler
    else:
        value = 0.0
    return None, value

programs.sol:
"""An orthographic out/ut feature with a negative English phrasal reading.

Internal 'out' spellings are positive, especially consonant clusters, tout,
and scout. English out-compounds are weaker. Standalone out is negative,
especially after come/turn/make/give/bring; 'out to' can continue that response.
Short rules cover French û spellings and following syllables, Japanese u-to,
and two unrelated formatting responses: initial 'Title:' and doubled middots.
These are approximate training means, not a complete account of the component.
"""
import re
from functools import cache
import wordnet

READS = ()

# Verb families: response on 'out', then on the 'to' in '... out to'.
VERBS = (
    ({'come', 'turn'}, -4.35, -4.63),
    ({'make', 'give', 'bring'}, -4.78, -2.21),
    ({'arise', 'grow'}, -3.84, -1.23),
    ({'get', 'put', 'break'}, -1.91, -1.03),
    ({'set', 'reach', 'miss', 'let', 'pick'}, -1.56, -1.39),
    ({'point', 'check', 'figure', 'filter', 'sort', 'run', 'watch'}, -.18, -.61),
)

# Different token endings dilute the internal-out response differently.
SPELLINGS = {
    'tout': 5.36,
    'toute': 4.15,
    'toutes': 1.40,
    'sout': 4.96,
    'bout': 4.12,
    'fout': 5.26,
    'rout': 3.60,
    'stout': 3.07,
    'trout': 2.02,
    'scout': 5.48,
    'scouts': 3.28,
    'scouting': 5.18,
    'shout': 1.75,
}
INTERNAL = {
    'oute': 2.17,
    'outes': .71,
    'outer': 1.35,
    'outing': 2.69,
    'outs': 2.84,
}
CLUSTER = {
    'oute': 5.56,
    'outes': .71,
    'outer': 8.27,
    'outing': 7.93,
    'outs': 6.82,
}


@cache
def bases(word):
    return set(wordnet.base_forms(word.lower())) | {word.lower()}


@cache
def verb_strength(word):
    for words, out, to in VERBS:
        if bases(word) & words:
            return out, to
    return -.59, -1.23


@cache
def out_compound(fragment):
    """Recognize dictionary-listed English word + out compounds/phrases."""
    match = re.search(r'[a-z]+$', fragment.lower())
    stem = match.group() if match else ''
    return (len(stem) > 2 and bool(wordnet.parts_of_speech(stem))
            and any(wordnet.parts_of_speech(stem + gap + 'out')
                    for gap in ('', '-', '_')))


def activation(token, previous, before_previous, position):
    t, p = token.strip(), previous.strip()
    low = t.lower()
    if not token:
        return 0.0
    if position == 1 and previous == 'Title' and token == ':':
        return -12.64
    if token == '··':
        return 1.34
    internal = (position > 0 and not token[0].isspace()
                and previous and previous[-1].isalpha()
                and not previous.endswith('\\n'))
    if low in ('out', '-out'):
        if internal and low == 'out':
            if t == 'Out' or out_compound(p):
                return -.16
            if re.fullmatch(r'gr|sp|spr|sc|sh|cr|str|sk|pr', p.lower()):
                return 8.46
            if p.lower().endswith('b'):
                return 9.48
            if re.fullmatch(r'[bcdfghjklmnpqrstvwxyz]{1,3}', p.lower()):
                return 4.39
            return 3.11
        if t == 'OUT':
            return .02
        if p.lower() in ('it', 'this', 'that', 'me', 'us', 'you', 'them'):
            p = before_previous.strip()
        return verb_strength(p)[0]
    if low in ('about', 'true') and bases(p) & {'come', 'turn'}:
        return -5.25 if low == 'about' else -7.76
    if low == 'about' and 'bring' in bases(p):
        return -2.98
    if low == 'to' and p.lower() == 'out':
        return verb_strength(before_previous.strip())[1]
    if low in ('come', 'comes') and p.lower().endswith('out'):
        return -3.78
    if low.startswith('outcom'):
        return -1.24
    if low == 'turnout':
        return -5.73
    if not token[0].isspace() and token[0].islower():
        out_tail = (p.lower().endswith('out')
                    and low in ('re', 'en', 'in', 'on', 'ons'))
        u_tail = p.endswith('û') and low in ('te', 'ter', 'tes')
        if out_tail or u_tail:
            return 4.25
    if low == 'cout':
        if p.lower().endswith(('é', 'e')) and not token[0].isspace():
            return 7.25
        return 4.12 if t[0].isupper() else .75
    if low in INTERNAL and internal:
        if out_compound(p):
            return -.16
        if p.lower() == 'r':
            return .11
        if p.lower() in ('sc', 'gr', 'sp', 'st', 'ch', 'br'):
            return CLUSTER[low]
        return INTERNAL[low]
    if low == 'tout' and p.lower() == 'avant':
        return 1.15
    if low in SPELLINGS:
        if low in ('tout', 'scout') and t[0].isupper():
            return 7.66 if low == 'tout' else 6.24
        return SPELLINGS[low]
    if low in ('ut', 'ute', 'utes', 'ût', 'üt'):
        return .22
    if t == 'û':
        if p.lower().endswith(('go', 'vo', 'cro')):
            return 5.79
        return 2.71 if p.lower().endswith('co') else .31
    if t == 'ト' and previous.endswith('ウ'):
        return 6.0
    if t == 'ート' and previous.endswith('チュ'):
        return 2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, position = '', '', 0
    else:
        _, previous, before_previous, position = carry
    token = prefix.token_strings[-1]
    value = activation(token, previous, before_previous, position)
    return (doc, token, previous, position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:1509: an "out / tout / scout" spelling detector.

What it does: the component writes a signed signal into the residual stream that
depends mostly on the spelling of the current token.

* Positive on "out" when it is a piece of a longer word rather than a word of its
  own, when the piece before it is a short fragment: "gr|out" (grout), "sp|out"
  (spout), "Sc|outing", "Deb|out|in". Strongest for the letters "out" glued on
  like this, weaker for "outer", "outs", "outing".
* Positive on the French "tout" / "toute" family (strongest), "Scout" and
  "scouting" (strong), and "cout" (weak). "tous" / "toutes" are weakly positive.
* Negative on the English particle "out" in its "result" sense: "turned out",
  "came out", "turns out to be", "come about", "come true", and on "turnout"
  and "outcome". Other particle uses of "out" (get out, check out) are mildly
  negative.
* Near zero elsewhere, including "out" in ordinary English words such as
  "cut out" or "break out", where the particle is a separate word.

The rule uses only the current token and the one or two tokens before it.
"""

READS = ()

# Words built on "scout"
SCOUT = {"scout", "scouts", "scouting"}
# French "tout" (all) and friends
TOUT = {"tout", "toute", "bout", "bouts", "sout"}
TOUS = {"tous", "toutes"}
# Verbs that take "out", "about" or "true" in the result sense
RESULT = {
    "turn", "turns", "turned", "turning", "come", "comes", "came", "coming",
    "made", "give", "gave", "bring", "brings", "brought", "bringing", "got",
}
OUTCOMES = {"outcome", "outcomes", "turnout"}
# Pieces of "out" that are not whole words
PIECES = {"out", "outs", "outing", "outer", "oute"}
# Short English words that take "out" as a separate particle
ENGLISH_SHORT = {
    "cut", "put", "set", "get", "let", "take", "pull", "break", "walk", "hang",
    "read", "run", "time", "wash", "print", "work", "find", "pick", "move", "go",
    "look", "shut", "check", "drop", "kick", "lay", "play", "stand", "try", "cop",
    "sum", "way", "spread", "fall", "log", "lock", "bail", "blow", "tip", "pay",
    "fire", "bring",
}


def glued_fragment(prev):
    """True when the previous piece is a short word fragment, like 'gr' or 'sp'."""
    return 0 < len(prev) <= 3 and prev.isalpha() and prev not in ENGLISH_SHORT


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1]
    s = w.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3].strip().lower() if len(prefix) > 2 else ""
    if s in SCOUT:
        return None, 6.0
    if s in TOUT:
        return None, 5.0
    if s in TOUS:
        return None, 1.0
    if s == "cout":
        return None, 1.5
    if s in OUTCOMES:
        return None, -1.5
    if w == " out":
        return None, -5.0 if prev in RESULT else -0.6
    if w == " to" and prev == "out":
        return None, -3.0 if prev2 in RESULT else -1.0
    if w == " about" and prev in RESULT:
        return None, -4.0
    if w == " true" and prev in RESULT | {"dream", "dreams"}:
        return None, -6.0
    if not w.startswith(" ") and s in PIECES and glued_fragment(prev):
        return None, 4.0
    return None, 0.0

programs.sol:
"""A small Chinese compound-completion predictor.

A word split across tokens gets its largest positive response when both
its dictionary entry and the new character's first listed sense are verbs.
Less clear verbal readings get smaller responses. Corpus frequency
separates familiar compounds from rare ones. Other text is near zero,
with a negative first-token baseline and a repeated-middle-dot response.
"""
from functools import lru_cache
from math import log10
import re
import regex
import cedict
from opencc import OpenCC
from wordfreq import get_frequency_dict

READS = ()
_HAN = regex.compile(r'\p{Script=Han}+')
_FREQUENCY = get_frequency_dict('zh')
_SIMPLIFY = OpenCC('t2s')

@lru_cache(maxsize=20000)
def senses(word):
    glosses = cedict.glosses(word)
    verbs = [bool(re.search(r'(^|\))\s*to ',g)) for g in glosses]
    return any(verbs), bool(verbs and verbs[0])

@lru_cache(maxsize=20000)
def frequency(word):
    f = _FREQUENCY.get(_SIMPLIFY.convert(word), 0)
    return max(0., log10(f) + 9) if f else 0.

@lru_cache(maxsize=50000)
def completion(previous, current):
    if not _HAN.fullmatch(current) or not _HAN.fullmatch(previous[-1:]):
        return 0.
    left, right = previous[-1], current[0]
    familiar = frequency(left + right)
    if senses(previous + right)[1]:
        if senses(right)[1]:
            return 0.17 if familiar < 3.8 else 0.42
        return 0.17 if senses(current)[0] else 0.02
    if familiar >= 3.2:
        return 0.07 if frequency(left) < 4.5 else 0.014
    return 0.004 if senses(previous)[0] else -0.013


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip()
    if len(current) > 1 and set(current) == {'·'}:
        return None, -0.815
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if start:
        return None, -0.134
    previous = prefix.token_strings[-2].strip()
    if '\ufffd' in previous:
        # Recover a character whose UTF-8 bytes were divided between tokens.
        positions = range(max(0, prefix.position - 3), prefix.position)
        raw = b''.join(prefix.token_bytes[j] for j in positions
                       if prefix.document_ids[j] == prefix.document_ids[-1])
        previous = raw.decode('utf-8', 'ignore')[-1:]
    return None, completion(previous, current)

"""Visible line separators and the indentation following them.

Escaped newlines, HTML breaks, table-row endings and TeX row breaks are
positive. Indentation after printed newlines or listing tabs is negative;
indentation after ordinary newlines is mostly quiet. Dense backtick/nbsp
code listings have a similar separator response. Printed newlines are stronger
in byte-escaped text and after numbers, weaker near real newlines or spaces.
Non-TeX doubled backslashes and merged escape fragments are generally negative.
Ordinary text stays zero. History is a 200-character tail, reset per document.
"""
import re

READS = ()
TEX = re.compile(r'\\(?:frac|sqrt|left|right|begin|text|overline|partial|lim)\b')


def predict(token, history):
    escaped_line = history.endswith('\\n')
    real_line = not history or history.endswith('\n')
    if token.isspace():
        if '\n' in token:
            return 0.5 if '\t' in token else 0.0
        if escaped_line:
            return -0.92 if len(token) < 3 else -1.6
        if '\t' in token and not real_line:
            return -0.35 - 0.035 * min(len(token) - 1, 28)
        if history.endswith('\t'):
            return -1.3
        if '\xa0' in token and len(token) >= 3:
            return -1.2
        if len(token) >= 3 and history.endswith(('//', '+', '|')):
            return -0.75
        return 0.0
    if token == '\\n' or history.endswith('\\') and token == 'n':
        if escaped_line:
            return 0.45
        before = history[:-1] if token == 'n' else history
        value = 1.0 if token == 'n' else 1.2
        if before[-1:].isspace():
            value -= 0.3
        if '\n' in history[-150:]:
            value -= 0.3
        if '\\x' in history:
            value += 0.65
        if before[-1:].isdigit():
            value += 0.5
        elif before[-1:].isupper() or before.endswith(tuple('{}()[]:;,')):
            value += 0.2
        return value
    if history.endswith('\\') and token.startswith(('n', 't')):
        if token == 't' or TEX.search(history):
            return 0.0
        if token.startswith('n') and token[1:2].isupper():
            return 1.0
        return -1.6 if len(token) == 2 else -0.7
    if len(token) - len(token.rstrip('\\')) >= 2:
        return 2.4 if TEX.search(history) or '$' in history else -1.3
    if history.endswith('\\\\') and token.startswith('\\'):
        return -1.4
    if token == '\\' and '\\n' in history:
        return 0.35
    if token == '|\n':
        return 1.1
    if token in ('<br', '<br/>') or token == 'br' and history.endswith('<'):
        return 1.0
    if token.count('`') == 1 and token.endswith('`'):
        if history.count('`') >= 6 and '\xa0' in history:
            if history.endswith('`'):
                return 0.5
            return 3.7 if token.strip() == '`' else 2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (history + token)[-200:]), value

"""A sparse lexical approximation, not a general detector of stopping.
Positive cues are stop and its inflections, stem(s), and Chinese stop markers.
Negative cues are the compound ending -bed and 'of' after most/best/rest/battle.
The preceding token supplies phrase, capitalization, and passive-voice cues;
it is forgotten at each document boundary. All other positions predict zero.
"""
import re

READS = ()
BE_FORMS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = previous.strip().lower()
    capital = previous.strip()[:1].isupper()
    value = 0.0
    if re.fullmatch(r'\W*stop(?:s|ped|ping)?', word):
        value = 5.5
        if word.endswith('stopped') and before in BE_FORMS:
            value = 2.8
        if word.startswith(('-', '.')):
            value = 6.5
    elif word in {'stem', 'stems'}:
        value = 2.5
    elif word in {'停', '不停', '停止', '止'}:
        value = {'停': 5.5, '止': 3.5}.get(word, 4.5)
    elif token == 'bed':
        value = -1.8 if before == 'test' else -1.4
    elif word in {'of', '-of'}:
        if before == 'most':
            value = -2.8
        elif before in {'best', 'rest'}:
            value = -6.3 if capital else -3.1
        elif before == 'battle':
            value = -7.0 if capital else -5.4
    return (doc, token), value

programs.haiku:
"""Stop detector for layers.1.mlp.down_proj:1515 (conceptual rules, no tables of ids).

What the component does: it reads the word being typed and writes a strong "stop" signal when
that word begins with "stop" (stop, Stop, stopped, stopping, stops, .stop(), _stop, one-stop,
or "St"+"opping"), and when the Chinese/Japanese character 停 (stop, as in bus stop) appears.
It writes a negative signal on the partitive "of" after most / rest / best / battle
("most of the", "rest of", "the Battle of"), and on "bed" in compounds such as testbed or
flatbed. Everything else is near zero.
"""
READS = ()

PARTITIVE_HEADS = {"most": -3.0, "rest": -3.0, "best": -3.0, "battle": -6.0, "last": -3.0}


def step(carry, prefix, upstream):
    # carry: (document id, letters of the word being typed so far, previous token)
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, previous = "", ""              # a new document starts a new word
    else:
        word, previous = carry[1], carry[2]
    for ch in token.lower():
        word = word + ch if ch.isalpha() else ""   # letters since the last non-letter

    value = 0.0
    if word.startswith("stop"):
        value = 5.0
    elif "停" in token:
        value = 3.5
    elif token == " of" and previous.strip().lower() in PARTITIVE_HEADS:
        value = PARTITIVE_HEADS[previous.strip().lower()]
    elif token == "bed":
        value = -1.5
    return (doc, word, token), value

programs.sol:
"""German-looking passages, with stronger responses to short word pieces.

Completed words vote for German versus English, Dutch, Danish, Swedish and
French, using dictionary frequencies. Two running averages track the local
language. Frequent complete German words are generally downweighted relative
to short, unfinished pieces. Dictionary prefixes provide weaker signals in
mixed passages. Historical long s gets an extra boost in German context.
Constants are fitted on training activations; token-specific peaks are omitted.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency, top_n_list

READS = ()
LANGUAGES = ('de', 'en', 'nl', 'da', 'sv', 'fr')
GERMAN_PREFIX = {}
for word in top_n_list('de', 60000):
    if word.isalpha():
        frequency = zipf_frequency(word, 'de')
        for length in range(1, len(word) + 1):
            stem = word[:length]
            GERMAN_PREFIX[stem] = max(GERMAN_PREFIX.get(stem, 0), frequency)

@lru_cache(maxsize=200000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., 0.)
    _, word, context, fast = carry
    prior_prefix = GERMAN_PREFIX.get(word, 0)
    token = prefix.token_strings[-1]
    for part in re.split(r'([^\W\d_]+)', token):
        if not part:
            continue
        if part.isalpha():
            word = (word + part.lower())[-60:]
        else:
            if len(word) > 1:
                f = frequencies(word)
                evidence = max(-3., min(3., f[0] - max(f[1:])))
                context = .9 * context + .1 * evidence
                fast = .6 * fast + .4 * evidence
            word = ''
    carry = (doc, word, context, fast)
    text = token.strip().lower()
    word_prefix = GERMAN_PREFIX.get(word, 0)

    if context <= .314:
        if fast <= .256:
            value = .247 if any(c in 'äöüßſ' for c in text) else .001
        elif fast <= .826:
            value = .035 if GERMAN_PREFIX.get(text, 0) <= 4.73 else .488
        elif word_prefix <= 3.74:
            value = .110 if len(word) <= 5 else .692
        else:
            value = .773 if prior_prefix <= 3.16 else 1.608
    elif not text.isalpha():
        if word_prefix > 6.71:
            value = 1.251
        else:
            value = .162 if prior_prefix <= 6.71 else .442
    elif frequencies(text)[0] <= 5.78:
        value = 2.058 if len(word) <= 4 else 1.142
    else:
        # Common German/Swedish forms retain more activation.
        value = .627 if frequencies(text)[4] <= 4.48 else 1.544
    if context > .314 and 'ſ' in text:
        value += 2.5
    return carry, value

"""Approximate a message-end response, plus a few smaller lexical effects.
End markers are positive (less so immediately after a tool's closing tag),
with a reduced response when little document/message context is available.
Selected Chinese/Japanese method, handling and regulation terms are negative.
A separate coarse rule covers the context-free first token of each document.
"""
import math
from functools import lru_cache
import opencc

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')
PREPOSITIONS = set('of to in for by on at from with into over under through '
                   'between as'.split())
PRONOUNS = set('i you we he she it they this that these those'.split())
CONJUNCTIONS = set('if and or but so because while when though unless'.split())


@lru_cache(maxsize=8192)
def chinese_form(token):
    return _SIMPLIFY.convert(token)


def initial_value(token):
    """Token shape and ordinary grammatical classes, without left context."""
    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    if token == '<|endoftext|>':
        return -2.48
    if token == '<|im_start|>':
        return 0.083
    if token == '<|im_end|>':
        return 0.686
    if token.startswith(('"""', "'''")):
        return -2.1
    if token == '//\n':  # an empty line comment
        return 4.0
    if token.startswith('#include'):
        return 0.43
    if token.startswith('#!/'):
        return -0.96
    if word == '.' and '\n' in token:
        return -1.8
    if word.isdigit():
        return 0.15
    if not word:
        return -0.09
    if lower in ('a', 'an', 'the'):
        return 0.11 if spaced else -0.42
    if lower in PREPOSITIONS:
        return 0.29 if spaced else -0.18
    if lower in PRONOUNS:
        return -0.11 if spaced else -0.39
    if lower in CONJUNCTIONS:
        return -0.20 if spaced else -0.11
    if not any(c.isalnum() for c in word):
        return -0.50 if '\n' in token else -0.21
    if word[0].isupper():
        return -0.17 if spaced else -0.29
    if word[0].islower():
        return -0.19 if spaced else -0.13
    return -0.10


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, 0, 0, '')
    _, position, message_length, previous = carry
    if token == '<|im_start|>':
        message_length = 0

    value = 0.004
    if first:
        value = initial_value(token)
    elif token == '<|im_end|>':
        short_message = 1 / math.sqrt(message_length + 1)
        short_document = 1 / math.sqrt(position + 1)
        beginning = math.exp(-position / 6)
        if previous in ('</tool_call>', '</tool_response>'):
            value = (1.67 - 0.42 * short_message
                     - 0.66 * short_document - 0.38 * beginning)
        else:
            value = (2.23 - 0.48 * short_message
                     - 0.61 * short_document - 0.26 * beginning)
    elif token == '</tool_call>':
        value = 0.32
    elif token == '</tool_response>':
        value = -0.15
    elif token == '</think>':
        value = 0.217
    elif token == '<think>':
        value = 0.095
    elif not token.isascii() and not token[:1].isspace():
        word = chinese_form(token)
        if word == '例' and chinese_form(previous).endswith('条'):
            value = -4.1  # the final character of 条例, regulations
        elif word.endswith('条例'):
            value = -2.5
        elif word.removeprefix('的') in ('方法', '办法'):
            value = -1.1  # method / means of handling something
        elif word == '管理办法':
            value = -2.8
        elif word in ('办', '怎么办'):
            value = -1.0
        elif word == '办理':
            value = -0.58
        elif word == '管理':
            value = -0.44
        elif word == '规定':
            value = -0.62
        elif word == '按规定':
            value = -1.8
    return (doc, position + 1, message_length + 1, token), value

"""Sparse spelling and phrase rules for occurrences, instances and examples.

The largest response is on 'of' in 'instance/example of', and on occurrence
words. Split occurrence roots are especially strong. A few smaller related
word families and negative CMS/ECMA, comic and currency spellings are
included. This is a lexical approximation, not a claim that all these
spellings have one meaning.
"""
import re

READS = ()
OCCURRENCE_ROOT = re.compile(r'(?:re)?(?:occur|ocur|ocor)')
COUNT_MODIFIERS = {'first', 'single', 'every', 'all', 'any', 'two', 'three'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, word = '', '', ''
    else:
        _, previous, before, word = carry
    s = prefix.token_strings[-1]
    low = s.lower()
    p = previous.strip().lower()
    current = low.strip()
    joined = low.lstrip() if s[:1].isspace() else word + low
    match = re.search(r'[a-z]+$', joined)
    new_word = match.group()[-30:] if match else ''
    value = 0.0

    if current == 'of':
        if p in ('instance', 'instances', 'example', 'examples'):
            value = 4.6
        elif p in ('copy', 'copies', 'illustration', 'illustrations'):
            value = 2.0
        elif p in ('ounce', 'ounces'):
            value = 1.0
        elif p in ('case', 'cases'):
            value = 0.5
        elif p == 'occurrences':
            value = 11.9 if before.strip().lower() == 'all' else 3.5
        elif OCCURRENCE_ROOT.match(word):
            value = 1.8
        else:
            value = 0.02
    elif current in ('instance', 'instances'):
        value = 3.1 if p in COUNT_MODIFIERS else (2.0 if current.endswith('s') else 1.0)
        if current == 'instance' and p == 'for':
            value = 0.0
    elif current.startswith('occurrence'):
        value = 4.3 if current.endswith('s') else 5.8
        if p == 'all':
            value = 12.5
    elif current in ('occ', '_occ'):
        value = 6.8 if p == '-' else 3.2
    elif current in ('occur', 'occurred', 'occurs', 'occurring'):
        value = 3.3 if current == 'occurring' else 2.5
        if p == 'naturally':
            value += 2.0
    elif OCCURRENCE_ROOT.match(new_word):
        # Completing a root across a token boundary is stronger than a whole word.
        value = 7.5 if not s[:1].isspace() else 3.0
        if OCCURRENCE_ROOT.match(word):
            value = 2.0
    elif re.match(r'(?:in|re|con)curr', new_word):
        value = 3.0 if not s[:1].isspace() else 0.7
        if current == 'recurrent':
            value = 2.1
    elif current.startswith('incur'):
        value = 1.0
    elif new_word.startswith('recog'):
        value = 1.0
        if current.startswith(('og', 'ogn')) or current in ('ize', 'ise'):
            value = 2.8
    elif current in ('incidence', 'recover'):
        value = 0.8
    elif word.endswith('acc') and low == 'um':
        value = 2.2

    # A negative orthographic side response: C-M clusters and ECMA names.
    if current == 'cms':
        value = -4.6
    elif p in ('ec', '_ec', '.ec', 'ic') and low == 'ma':
        value = -6.3
    elif p in ('ec', '_ec') and low == 'm':
        value = -4.9
    elif previous.strip().isupper() and p.endswith('c') and s == 'MS':
        value = -4.0
    elif current.startswith(('comic', 'currency')):
        value = -1.1 if current.startswith('comic') else -0.35

    return (doc, s, previous, new_word), value

programs.haiku:
"""Layer-1 MLP down-projection component 1520.

A word-pattern detector. It responds to:
1. "of" right after an exemplar noun: "an instance of", "an example of" (strong, about 4.5),
   "a copy of", "an illustration of", "a quotation of" (weaker, about 2.5). The exemplar
   noun itself ("instance", "example") gives a smaller response, about 1.
2. The "occur" word family, read piece by piece: the response is on the letters of the word
   typed so far. "occurrence" and "occurring" are strongest (about 4.5); "occur", "occurs",
   "occurred" about 2.5; "incurred" about 1.7; a bare "occ" about 3.5.
3. A negative response, about -6, on "ma" in "ecma" (as in "ecmaVersion").
Everywhere else it predicts 0; the typical activation is near zero, so this is the
component's main response.
"""
import re

READS = ()

EXEMPLAR_NOUNS = {" instance", " instances", " example", " examples", " Examples", " Example"}
OTHER_EXEMPLARS = {" copy", " copies", " illustration", " illustrations", " quotation"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    word = re.search(r"[A-Za-z]*$", prefix.text_prefixes[-1]).group(0).lower()
    if cur == " of":
        if prev in EXEMPLAR_NOUNS:
            return None, 4.5
        if prev in OTHER_EXEMPLARS:
            return None, 2.5
        return None, 0.0
    if cur in EXEMPLAR_NOUNS:
        return None, 1.0
    if word == "ecma":
        return None, -6.0
    if "occurr" in word or "occurring" in word:
        return None, 4.5
    if "occur" in word:
        return None, 2.5
    if "incur" in word:
        return None, 1.7
    if len(word) >= 3 and "occur".startswith(word):
        return None, 3.5
    return None, 0.0

programs.sol:
"""A boundary-sensitive detector for written numbers.

Usually mark a number's first digit, especially after whitespace. Digits
after dots, carets or Latin letters are weaker; digits after non-Latin
letters remain strong. Track line starts to distinguish indented numbers.
Also mark the century prefixes 19 and 20, and (more weakly) round tens.
Document-initial tokens get a separate, coarse baseline by token type;
these estimates cannot capture all of their large lexical variation.
"""
READS = ()
PREPOSITIONS = set('in of to on at as by for from over under with without '
                   'into through between about after before during'.split())
FUNCTION_WORDS = set('the a an this that these those and or but if i you he '
                     'she it we they is are was were be been being have has '
                     'had do does did can could will would may might must '
                     'shall should not'.split())
CODE_KEYWORDS = set('class package import def function const var let public '
                    'private protected static export namespace using module'.split())


def separator(text):
    if text.endswith('\n') or text.endswith('\\n'):
        return 'newline'
    if text[-1:].isspace():
        return 'space'
    if text[-1:].isalpha():
        return 'latin' if text[-1:].isascii() else 'nonlatin'
    return text[-1:]


def initial_value(token, digit):
    word = token.strip().lower()
    if digit:
        return -0.28 if token == '0' else 4.0
    if token.startswith('<|'):
        return 3.13
    if token.isspace():
        return 1.2 if '\t' in token else 2.1 if '\n' in token else 4.7
    if token in ('.', '#'):
        return 6.3
    if not any(ch.isalnum() for ch in token):
        return 3.1
    if word in FUNCTION_WORDS:
        return -0.08
    if word in PREPOSITIONS:
        return 1.68
    if token.strip() in CODE_KEYWORDS:
        return 4.0
    if len(word) == 1 and word.isascii() and word.isalpha():
        return 0.12
    return 0.75


def number_value(number, boundary):
    token = number[-1]
    if len(number) == 1:
        if boundary == 'indent':
            value = 1.5 if token == '1' else 1.2 if token == '2' else 1.28
        elif boundary in ('space', 'newline', 'nonlatin'):
            value = 0.9 if token == '2' else 1.05
            if token == '1':
                value = 1.95 if boundary == 'newline' else 1.15
        elif boundary in ('.', '^'):
            value = -0.02
        else:
            if boundary == 'latin':
                value = 0.28
            elif boundary == ',':
                value = 0.34
            elif boundary in ('-', '+', '/'):
                value = 0.45
            else:
                value = 0.7
            value += 0.17 if token == '0' else -0.16 if token == '2' else 0
        return value

    if number in ('19', '20'):
        if boundary in ('space', '('):
            value = 1.42 if number == '19' else 1.2
        elif boundary == 'nonlatin':
            value = 1.35
        elif boundary in ('newline', '/', '–'):
            value = 0.85
        elif boundary in ('indent', 'latin'):
            value = 0.5
        else:
            value = 0.35
    elif token == '0':
        previous_digit = number[-2]
        if previous_digit == '1':
            if len(number) > 2:
                value = 0.28
            elif boundary == 'indent':
                value = 0.76
            elif boundary == 'space':
                value = 0.67
            else:
                value = 0.5
        elif previous_digit == '3':
            value = 0.42 if len(number) == 2 else 0.26
        elif previous_digit == '2':
            value = -0.15
        else:
            value = 0.1
    else:
        if boundary in ('indent', 'nonlatin'):
            value = 0.01
        elif boundary == 'latin' and len(number) <= 3:
            value = -0.17
        else:
            value = -0.15 if token in '25' else -0.02
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        number, boundary, at_line_start = '', '', True
    else:
        _, number, boundary, previous, at_line_start = carry
    digit = len(token) == 1 and token in '0123456789'
    if digit:
        if not number:
            boundary = '' if initial else separator(previous)
            if not initial and at_line_start and boundary != 'newline':
                boundary = 'indent'
        number += token
    else:
        number = ''
    line_text = token.replace('\\n', '\n')
    if '\n' in line_text:
        at_line_start = not line_text.rsplit('\n', 1)[-1].strip()
    else:
        at_line_start = at_line_start and not line_text.strip()
    state = (doc, number, boundary, token, at_line_start)
    if initial:
        return state, initial_value(token, digit)
    if not digit:
        return state, -0.005
    return state, number_value(number, boundary)

"""Recognize PICK-UP constructions and cup/up-like spelling fragments.

PICK + UP is the strongest response, including inflected PICK and an
intervening object pronoun. Other phrasal verbs have smaller, often negative
responses. CUP, CUP OF, and split cup/cip syllables form a second positive
family. These are surface-spelling rules, not a general meaning of 'up'.
The last 100 characters supply local context; documents reset that context.
Other responses are left at zero.
"""
import re
import unicodedata
from functools import lru_cache
import wordnet

READS = ()

# Familiar phrasal-verb constructions, grouped across inflections.
UP_VERBS = {
    'pick': 13.0, 'take': 4.0, 'back': 0.7, 'clean': 0.7,
    'catch': 0.7, 'wake': 1.0, 'sign': 0.7, 'hook': 0.7,
    'buckle': 2.5, 'suck': 2.5, 'perk': 1.7, 'crank': 1.3,
    'set': 0.0, 'make': 0.0, 'follow': -0.3,
    'open': -3.2, 'put': -3.3, 'give': -2.7,
    'lead': -4.5, 'pass': -4.5, 'divide': -4.0,
    'write': -4.0, 'roll': -3.4, 'work': -3.6, 'post': -3.6,
    'play': -3.0, 'run': -2.6, 'come': -1.8, 'go': -1.8,
    'move': -1.7, 'add': -1.6, 'bring': -0.8,
    'close': -3.8, 'runner': -4.0,
}
OBJECTS = {'it', 'him', 'her', 'them', 'you', 'me', 'us', 'em'}


@lru_cache(maxsize=2048)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=2048)
def verb(word):
    if word in UP_VERBS:
        return word
    for base in wordnet.base_forms(word):
        if base in UP_VERBS:
            return base
    return word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    text = prefix.token_strings[-1]
    token = text.strip()
    lower = plain(token)
    words = re.findall(r"[a-z]+", plain(tail))
    word = words[-1] if words else ''
    base = word
    if lower in {'up', '-up', 'ups', '-ups', 'with'}:
        base = verb(word)
    value = 0.0

    if lower in {'up', '-up', 'ups', '-ups'}:
        attached = not text[:1].isspace()
        value = UP_VERBS.get(base, 0.0 if attached else -1.1)
        if base == 'back' and attached:
            value = 3.3
        if base == 'pick':
            if word == 'picks':
                value += 3.0
            elif word == 'picked':
                value += 1.0
            if lower == '-up':
                value += 5.0
        if word in OBJECTS:
            earlier = [verb(w) for w in words[-4:-1]]
            value = -0.5
            if 'pick' in earlier:
                value = 7.5
            elif 'take' in earlier:
                value = 2.5
        if attached and token != token.lower():
            value = 0.0
        if (lower in {'up', 'ups'} and attached
                and plain(previous).endswith('c')
                and (token.islower() or previous.strip() == 'C')):
            value = 14.0 if plain(previous).endswith('ec') else 7.0
        elif (lower in {'up', 'ups'} and attached and token.islower()
              and plain(previous).endswith('k')
              and base not in UP_VERBS and not word.endswith('ook')):
            value = 4.0
    elif lower == 'pickup':
        value = 13.0
    elif lower in {'cup', 'cups', 'coup', 'coupe'}:
        value = 1.7 if token[0].islower() else 2.1
        if word in {'hic', 'por'} and not text[:1].isspace():
            value = 10.0
        if word == 'world':
            value = 0.9
        elif word == 'fa':
            value = 4.8
    elif lower in {'recup', 'recuper', 'preocup', 'preoccup', 'ocup', 'occup'}:
        value = 5.0 if lower.startswith(('rec', 'pre')) else 2.0
        if word == 'pre':
            value = 7.0
    elif token in {'куп', 'cập', 'カップ'} or lower == 'kup':
        value = 3.0

    # A syllable split after c/k: occ|ipital, oc|upa, C|UP, к|уп.
    if not text[:1].isspace():
        last = plain(previous).rstrip()
        if (last.endswith('c')
                and lower in {'ip', 'upa', 'upe', 'uper', 'upid', 'oup'}):
            value = 3.3
        if last.endswith(('к', 'k')) and token == 'уп':
            value = 4.0
        if lower == 'occupied' and word == 'pre':
            value = 4.4
        if lower == 'cake' and word == 'cup':
            value = 4.2
        if lower in {'ere', 'ar', 'ation'} and word.endswith(('recup', 'recuper')):
            value = 4.0
    if lower == 'of' and word in {'cup', 'cups'}:
        value = 4.0
    if lower == 'with' and word == 'up' and len(words) > 1:
        prior = verb(words[-2])
        if prior == 'come':
            value = -2.0 if words[-2] == 'came' else -3.0
        elif prior in {'keep', 'put'}:
            value = -0.8
    return (doc, (tail + text)[-100:], text), value

"""Local phrase and spelling-fragment detector.

Forms of be after 'which' give negative pulses, strongest for 'is'.
After 'who', the same four forms give much weaker negative pulses.
Other large negative responses follow short h-centered spellings: hol(e), hof, h-vowel-z, and ohem.  These can straddle a token
boundary.  Spaced word starts are weaker than within-word fragments.
A few h continuations give smaller positive responses instead.
"""
import re

READS = ()
BE = {'is': -3.7, 'are': -1.9, 'was': -1.65, 'were': -1.4}


def spelling(previous, token):
    word = token.strip().lower()
    spaced = token[:1].isspace()
    fragment = word.lstrip('_./-')
    joined = False
    if token[:1].isalpha():
        for tail in ('hol', 'ho', 'he', 'hö', 'h'):
            if previous.lower().endswith(tail):
                fragment = tail + word
                joined = True
                break
    if re.fullmatch(r'h[oeö]z', fragment):
        return -8.0
    if re.fullmatch(r'hol(?:e[s]?|en|ing|z)?', fragment):
        if joined:
            return -6.0
        if fragment == 'hol':
            return -1.8 if spaced else -5.0
        return -4.5 if spaced else -7.0
    if fragment == 'hof':
        return -5.0 if joined else -1.7 if spaced else -3.7
    if word == 'hem' and not spaced and previous.lower().endswith('o'):
        return -5.3
    if fragment.startswith('ho'):
        return -0.05 if spaced and not joined else -0.5 if joined else -0.6
    if fragment.startswith('hir'):
        return 0.8
    if joined and word.startswith('an'):
        return 0.3
    if joined and token.isupper():
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    pronoun = previous.strip().lower()
    if pronoun == 'which' and word in BE:
        value = BE[word]
    elif pronoun == 'who' and word in BE:
        value = 0.15 * BE[word]
    else:
        value = spelling(previous, token)
    return (doc, token), value

programs.haiku:
"""Layer-1 MLP down_proj direction 1523: a 'which is' / 'hole' detector.

Strongly negative on
  * the verb right after the relative pronoun "which": ", which is" (about -4),
    "the X which is" (about -3), ", which was/are" (about -2), "of which are" (about -1.5);
  * the word "hole"/"holes" (also "bore-hole", "pocket hole", "rat holes"), about -4 to -5;
  * "hose" (and the Korean 호스 'hose', via its final syllable 스), about -3;
  * the bare word-pieces "hol", "house" and "host" inside compounds, about -1.5 to -2.5.
Elsewhere it is roughly 0; its small everyday activity is not modelled here.
"""

READS = ()

HOLE_EXACT = {"hole": -4.5, "holes": -4.5, "oles": -4.5, "hose": -3.0, "hoses": -3.0}
HOLE_PIECE = {"hol": -2.5, "house": -2.0, "host": -1.5}
VERB_AFTER_WHICH = {"is": -3.2, "are": -1.5, "was": -1.5, "were": -1.5}
VERB_AFTER_COMMA_WHICH = {"is": -4.0, "are": -2.5, "was": -1.8, "were": -2.5}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip("-_").lower()
    n = len(prefix)
    same_doc = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    before = prefix.token_strings[-3].strip() if n > 2 and same_doc else ""
    if prev == "which" and word in VERB_AFTER_WHICH:
        if before == ",":
            return carry, VERB_AFTER_COMMA_WHICH[word]
        return carry, VERB_AFTER_WHICH[word]
    if raw == "스" and prefix.text_prefixes[-1].endswith("호스"):
        return carry, -3.0
    if word in HOLE_EXACT:
        return carry, HOLE_EXACT[word]
    if raw.startswith(" ") and word in ("house", "host"):
        return carry, 0.0
    if word in HOLE_PIECE:
        return carry, HOLE_PIECE[word]
    return carry, 0.0

"""Document-opening spike of layer-1 MLP unit 1524 (down_proj).

What it does: the unit is silent everywhere except on the first token of a document (the
first token after a document break, or the first token of a row, where the model has no
earlier context). There its output is large, and its size is set by what that token is:

  * a code or markup opener with no leading space ("using", "package", "import", "from",
    "def", "namespace", "#", "#include", "/*", "//", "<?", "@") gives the largest values
    (about +9 on top of the base);
  * a common English function word or sentence opener ("the", " of", " to", "How", "If",
    "In", "We") gives a moderate boost (about +3);
  * any other first token sits at the base level, about +3.7;
  * the chat-turn marker "<|im_start|>" gives +3.5; the end-of-text marker "<|endoftext|>"
    is set to -5.6 (it is almost never a real document opener);
  * a CJK character, a bare newline or whitespace token, or a punctuation-only token
    gives a negative adjustment (about -1.2 to -2.6).

Why: with no preceding context, this unit reads a property of the first token itself:
whether it is the usual way a file or sentence begins. The coefficients are least-squares
fits to the activation at document starts, for every vocabulary token, weighted by how
often that token starts a document in the training rows. Every other position is 0.
"""

import re

READS = ()

# Tokens that open a line of code or markup (no leading space).
CODE_OPENER = re.compile(
    r"^(#|@|/\*|//|<\?|using\b|import\b|from\b|def\b|class\b|package\b"
    r"|namespace\b|include\b|pragma\b|use\b|var\b|let\b|const\b|function\b|public\b"
    r"|private\b|static\b|return\b|module\b|export\b|require\b|async\b|await\b"
    r"|struct\b|void\b)"
)
CJK = re.compile(r"[⺀-鿿가-힯぀-ヿ]")
# Common English function words and sentence openers.
FUNCTION_WORDS = frozenset(
    "the a an of to in on for with from by at and or but is are was were be it this "
    "that these those we they he she you i how what when where why who which if do does "
    "can will would should as into after before than so not my your our their there here".split()
)


def _document_start(prefix) -> bool:
    if prefix.position == 0:
        return True
    return prefix.document_ids[-1] != prefix.document_ids[-2]


def step(carry, prefix, upstream):
    if not _document_start(prefix):
        return carry, 0.0
    token = prefix.token_strings[-1]
    word = token.lstrip(" ")
    if token == "<|endoftext|>":
        return carry, -5.6
    value = 3.7
    if token == "<|im_start|>":
        value += 3.5
    if CODE_OPENER.match(token):
        value += 9.0
    if word and word.lower() in FUNCTION_WORDS:
        value += 3.0
    if CJK.search(token):
        value -= 1.5
    if token.strip() == "" or "\n" in token:
        value -= 2.6
    elif word and not any(ch.isalnum() for ch in word):
        value -= 1.2
    return carry, float(value)

programs.sol:
"""Approximate spaces interrupting Latin-script words.

Compare a joined word beginning with the two pieces as independent words,
using wordfreq dictionaries. Zipf frequencies are logs of counts per billion,
so joined + 9 - left - right measures evidence for joining the pieces.
Give a negative response only for strong evidence; weaken it for ordinary
hyphenation and capitalized pieces. This misses many unusual OCR fragments.

Ordinary tokens get a small length-dependent background. Document starts get
a positive pulse, and the colon in an initial 'Title:' label gets -3.85.
All context is causal and resets at document boundaries.
"""
import regex as re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl')
WORDS = {}
BEGINNINGS = {}
for language in LANGUAGES:
    words, beginnings = {}, {}
    for word in top_n_list(language, 100000):
        if not word.isalpha():
            continue
        frequency = zipf_frequency(word, language)
        words[word] = frequency
        for length in range(1, min(len(word), 18) + 1):
            part = word[:length]
            beginnings[part] = max(beginnings.get(part, 0), frequency)
    WORDS[language] = words
    BEGINNINGS[language] = beginnings

@lru_cache(200000)
def interrupted_word(left, right):
    left, right = left.lower(), right.lower()
    joined = max(BEGINNINGS[l].get(left + right, 0) for l in LANGUAGES)
    if joined < 2.5:
        return -20
    independent = max(
        max(1.5, WORDS[l].get(left, 0)) + max(1.5, WORDS[l].get(right, 0))
        for l in LANGUAGES
    )
    evidence = joined + 9 - independent
    # Do not mistake two ordinary foreign words for broken English.
    if evidence > 4.5:
        for language in ('sv', 'da', 'nb', 'fi', 'pl', 'cs', 'ro', 'tr'):
            separate = max(1.5, zipf_frequency(left, language))
            separate += max(1.5, zipf_frequency(right, language))
            evidence = min(evidence, joined + 9 - separate)
    return evidence

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != document
    if start:
        recent, position, previous = '', 0, ''
    else:
        _, recent, position, previous = carry
        position += 1
    value = -0.005
    letters = token.strip()
    if letters.isalpha() and token.startswith(' '):
        value = -0.003 * max(1, len(letters) - 1)
    if start:
        if letters[:1].isalpha():
            value = 0.40 if len(letters) <= 4 else 0.30
            if token.startswith(' '):
                value -= 0.06
        elif not letters:
            value = 0.10
        else:
            value = 0.22 if len(letters) <= 6 else 0.06
    elif position == 1 and previous == 'Title' and token == ':':
        value = -3.85
    else:
        right = re.fullmatch(r'([ \t\n]*)(\p{Latin}+)', token)
        left = re.search(r'(\p{Latin}+)([ \t\n-]*)$', recent)
        if right and left and (right[1] or left[2]):
            if len(left[1]) <= 18 and len(right[2]) <= 18:
                score = interrupted_word(left[1], right[2])
                if score > 4.5:
                    response = min(0.85, 0.2 * (score - 4.1))
                    if '-' in left[2]:
                        response *= 0.5 if right[1] else 0.1
                    if right[2][0].isupper():
                        response *= 0.4
                    value = min(value, -response)
    recent = (recent + token)[-50:]
    return (document, recent, position, token), value

"""A spelling-based approximation, concentrated on court/cour and coast.

Court spellings give a negative response, amplified in formal court titles
and on a following 'of'. Token boundaries matter: c + ourt is especially
strong, while cord/concord/discord and c + ord have the opposite sign.
Small nearby spelling effects are omitted. Numbers are fitted on training
text; this is not a general classifier of legal subject matter.
"""
import re

READS = ()
SPELLINGS = {
    'court': -7.1, 'courts': -7.1,
    'cour': -4.1, 'cours': -4.1, 'course': -0.4,
    'coast': -2.7, 'coastal': -1.0, 'coastline': -1.0,
    'cord': 1.7, 'concord': 3.3, 'discord': 3.3,
}
AFTER_OF = {'court': -7.1, 'courts': -7.1, 'course': -4.2,
            'coast': -1.5, 'code': -1.7}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    text = prefix.token_strings[-1]
    lower = text.lower()
    token = lower.strip(" \t\n\r._/-()[]{}'\"\\")
    old = word.lower()
    joined = bool(word and re.match(r'^[A-Za-z]', text))
    value = SPELLINGS.get(token, 0.0)

    if token in ('court', 'courts'):
        if text.strip().isupper():
            value -= 5.2
        if joined:
            value -= 1.3
        if old in ('district', 'circuit'):
            value -= 4.7
        elif old in ('superior', 'appellate'):
            value -= 3.4
        elif old in ('the', 'a', 'an'):
            value += 1.1
        elif old in ('this', 'that', 'these', 'those'):
            value += 3.2
    elif token == 'coast':
        if text.strip()[:1].isupper():
            value -= 1.8
        if old in ('gold', 'ivory', 'orange'):
            value -= 1.6

    if joined:
        if old.endswith(('c', 'k')):
            if lower.startswith('ourt'):
                value -= 10.7
            elif lower.startswith('our'):
                value -= 5.5 if lower in ('our', 'ours') else 0.8
            elif lower.startswith('ord'):
                value += 4.0 if lower in ('ord', 'ords') else 1.7
        if old.endswith('cour'):
            value -= 3.4 if len(text) <= 3 else 1.4
        if old.endswith('cor') and lower.startswith(('r', 't')):
            value -= 3.2 if len(text) <= 3 else 1.1
        if old.endswith('co') and lower.startswith(('ast', 'at', 'ars')):
            value -= 2.0

    if token == 'of':
        if old.endswith('court'):
            old = 'court'
        elif old.endswith('courts'):
            old = 'courts'
        value += AFTER_OF.get(old, 0.0)
        if old in ('court', 'courts'):
            if previous.strip()[:1].isupper():
                value -= 3.2
            if text.strip().isupper():
                value -= 2.4

    tail = re.search(r'[A-Za-z]+$', text)
    word = (word + text if joined and re.fullmatch(r'[A-Za-z]+', text)
            else tail.group()) if tail else ''
    return (doc, text, word[-64:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:1528: a "court" detector.

What it does: this component goes strongly negative on the word "court" (and "courts",
"COURT", and the pieces "ourt", "cour", "cort" that the tokenizer splits some spellings
into). It is most negative when the court is named as a court of law, as in
"District Court", "Superior Court", "United States Court of Appeals" (about -10 to
-12), and weak after "this" ("this Court", about -2.5). The "of" right after a court
word ("Court of", "COURT of") is also strongly negative, and "course of" less so. "Coast"
is moderately negative. Everything else is predicted as 0.

Why: it is a sparse, lexical component: about 0.1% of tokens, nearly all of them these
words. A short list of words with a few context rules captures most of its variance; the
long tail of small effects on other words (about +-1) is left at 0.
"""

READS = ()

COURT_WORDS = {"court", "courts"}
COURT_PIECES = {"cour", "cours", "cort"}  # other pieces of "court" spellings
COAST_WORDS = {"coast"}
# words that name a court, so that the next word is a court name
COURT_NAMERS = {"district", "superior", "circuit", "states", "federal", "high",
                "appellate", "trial", "state", "county", "municipal", "city"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "of" and (prev in COURT_WORDS or prev == "ourt"):
        return None, -10.0  # "Court of", "COURT of"
    if word == "of" and prev == "course":
        return None, -4.5  # "course of"
    if word == "ourt":
        return None, -10.0  # the piece "ourt" of a split spelling, as in "Acc|ourt"
    if word in COURT_WORDS:
        if raw.strip().isupper():
            return None, -12.0  # "COURT"
        if prev in COURT_NAMERS:
            return None, -10.0  # "District Court"
        if prev == "this":
            return None, -2.5  # "this Court"
        return None, -6.5
    if word in COURT_PIECES or word in COAST_WORDS:
        return None, -4.0
    return None, 0.0

"""Word-fragment detector for layers.1.mlp.down_proj:1529.

What it responds to: a token that continues a word, i.e. a piece the tokenizer cut out of
the middle or end of a longer word (no leading space, letters only: "ONY" in
"ANONYMIZED", "oc" in "rhinoceros", "ро" inside a Russian word). Whole words, word-initial
pieces (leading space), capitalised pieces (names, sentence starts), digits, punctuation
and CJK characters predict 0.

How strongly: the values are the average activation per class, fitted on 4096 training
rows. Short lowercase Latin pieces (2-3 letters) are strongest; non-Latin alphabetic pieces
(Cyrillic, Greek, accented letters) are strong when short; long pieces are weak.

The program keeps no state: it reads only the newest token and whether it starts a document.
"""

READS = ()


def _is_cjk(c):
    """Kana, CJK ideographs, Hangul syllables and compatibility ideographs."""
    return (
        "぀" <= c <= "ヿ"
        or "㐀" <= c <= "鿿"
        or "가" <= c <= "힯"
        or "豈" <= c <= "﫿"
    )


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_document = prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if new_document or s[:1].isspace() or not s.isalpha() or _is_cjk(s[0]):
        return carry, 0.0
    n = len(s)
    if s.isascii():
        if s.istitle():
            return carry, 0.0
        if s.islower():
            value = {1: 0.12, 2: 0.30, 3: 0.23, 4: 0.13}.get(n, 0.04)
        else:
            value = {2: 0.10, 3: 0.18, 4: 0.15}.get(n, 0.06)
    else:
        value = 0.45 if n <= 3 else 0.16
    return carry, float(value)

programs.sol:
"""Approximate a sparse, tokenization-sensitive g-spelling response.

Git spellings are positive; generally and in general are negative. For split
words, a short signed table estimates the syllable following g: notably
positive ill/ull/or and negative a/e families, with stronger stem completions.
There are also rules for Greek gamma+nu, Cyrillic gen+er, and Gurmukhi ga+nna.
These are spelling approximations, not a general pronunciation rule.

State holds the previous token and a short byte tail (for split UTF-8), and
resets between documents. Unrecognized tokens receive a near-zero value.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text).lower()


def alphabetic(ch):
    return ch.isalpha() and any(
        script in unicodedata.name(ch, '')
        for script in ('LATIN', 'GREEK', 'CYRILLIC')
    )


def syllable(s):
    # Full syllables first, then their initial two-letter families.
    if s in ('ill', 'ills'):
        return 8.7
    if s in ('ull', 'ulls'):
        return 2.5
    if s.startswith('ouv'):
        return -3.4
    if s.startswith(('ove', 'era', 'eni', 'ama', 'aba', 'ast')):
        return -1.6
    if s == 'ore':
        return 2.4
    pairs = {
        'or': 1.7, 'ol': 0.9, 'op': 1.0, 'oc': 1.0, 'of': 1.1,
        'il': 0.8, 'ix': 2.6, 'ar': 0.3, 'em': 0.35,
        'ak': -1.6, 'au': -1.4, 'ab': -1.0, 'ag': -0.8,
        'an': -0.75, 'as': -0.5, 'am': -0.3, 'aw': -1.0,
        'en': -0.3, 'er': -0.35, 'eg': -0.9, 'ig': -0.8,
        'ou': -0.5, 'ov': -0.3, 'ub': -1.3,
    }
    return pairs.get(s[:2], 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same = carry is not None and carry[0] == doc
    previous = carry[1] if same else ''
    recent = (carry[2] if same else b'') + prefix.token_bytes[-1]
    recent = recent[-12:]
    raw = prefix.token_strings[-1]
    current = spelling(raw)
    word = current.strip(' ._/-\t\n')
    prev = spelling(previous)
    value = -0.002

    if word == 'git':
        if raw.startswith('.'):
            value = 2.5
        elif prev.rstrip().endswith('.'):
            value = 4.8
        elif not previous or not previous[-1:].isalpha() or raw[:1].isspace():
            value = 3.3
    elif current == '.com' and prev.endswith(('github', 'ithub')):
        value = 1.4
    elif word == 'generally':
        value = -0.2 if prev.strip() == 'more' else -1.95
    elif word == 'general':
        if prev.strip() == 'in':
            value = -1.2
        elif prev.strip() in ('attorney', 'orney', 'gnu'):
            value = -0.75
        else:
            value = -0.1
    elif word in ('gill', 'gil', 'gore', 'gor', 'gol'):
        value = {'gill': 4.0, 'gil': 1.1, 'gore': 2.6,
                 'gor': 0.8, 'gol': 1.2}[word]
    elif recent.endswith('ਗਣ'.encode('utf-8')):
        # Gurmukhi ga + retroflex nna, including a split UTF-8 character.
        value = -6.1
    elif raw.startswith('ν') and 'γ' in previous.lower():
        value = -4.5 if prev.endswith('e') else -2.3
    elif 'ген' in previous.lower() and raw.lower().startswith('ер'):
        value = -4.7
    elif previous and raw and alphabetic(previous[-1]):
        fragment = re.split('[^a-z]', prev)[-1]
        if 'g' in fragment:
            tail = fragment.rsplit('g', 1)[1]
            if not tail or len(fragment) <= 5:
                joined = 'g' + tail + current
                strength = 1.0
                if fragment.endswith('ig'):
                    strength = 0.18
                elif fragment.endswith(('ag', 'eg', 'og')):
                    strength = 0.5
                if not tail and current in ('ener', 'ender'):
                    value = -5.8 * strength
                elif not tail and current in ('it', '++', 'cc', 'pp'):
                    # Split Git, G++, GCC and (3)GPP identifiers.
                    value = 6.5 if current == 'pp' else 4.8 * strength
                elif joined.startswith(('genan', 'genaus')):
                    value = -5.2
                elif joined.startswith(('generally', 'generalement')):
                    value = -3.5
                elif joined.startswith('guana'):
                    value = -2.6
                elif current and alphabetic(raw[0]):
                    value = strength * syllable(tail + current)
    return (doc, raw, recent), float(value)

"""Han-script action words in noun-like contexts.

A dictionary's 'to ...' gloss identifies an action. Such words receive a
small positive signal, strengthened after 的, especially in '对 X 的 action'
constructions. Single Han characters are instead tested as compound endings.
Japanese action-noun glosses supplement Chinese compound lookups. Accusative
particles and Japanese adjective endings receive small negative signals.
This approximates the grammatical pattern, not individual word strengths.
"""
from functools import lru_cache
import re
import regex
import cedict
import jmdict
import wordnet

READS = ()
HAN = regex.compile(r'\p{Script=Han}+')
CLAUSE_END = re.compile(r'[。，！？；,!?;\n]')


@lru_cache(maxsize=32768)
def action(word):
    return any(gloss.startswith('to ') for gloss in cedict.glosses(word))


@lru_cache(maxsize=32768)
def japanese_action(word):
    for gloss in jmdict.glosses(word):
        gloss = re.sub(r'\([^)]*\)', '', gloss).strip()
        categories = wordnet.categories(gloss, 'noun')
        if categories & {'noun.act', 'noun.process', 'noun.cognition'}:
            return True
    return False


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, clause = '', ''
    else:
        _, previous, clause = carry
    raw = prefix.token_strings[-1]
    text = raw.strip()
    value = 0.0
    if HAN.fullmatch(text):
        possessive = previous.endswith('的')
        if len(text) > 1 and text.startswith('的'):
            text = text[1:]
            possessive = True
        single = len(text) == 1
        is_action = action(text)
        if is_action and not single:
            value += 0.13
            if possessive:
                value += 0.45
                if re.search(r'[对對与與].{0,60}$', clause):
                    value += 0.85
        if single and previous and HAN.fullmatch(previous[-1]):
            compound = previous[-1] + text
            if action(compound):
                value += 0.14
            if japanese_action(compound):
                value += 0.17
        if previous.endswith('の') and is_action:
            value += 0.06
    elif text in {'を', '을', '를'}:
        value = -0.15
    elif text in {'な', 'い'}:
        value = -0.20
    clause = CLAUSE_END.split((clause + raw)[-70:])[-1]
    return (document, raw, clause), value

programs.haiku:
"""Layer-1 MLP down_proj component 1531 (weak, sparse explanation).

The component is near zero almost everywhere. It rises on Chinese words that head a phrase:
a two-character Chinese word (verb or abstract noun such as 关联, 论述, 推进, 实现, 制定,
说明, 区别) that directly follows a possessive 的 ("X的关联", "详细的说明", "对相关概念的论述"),
or that follows a connective (和, 与, 及, 进行, 对, 将). The strongest cases are after 的;
the weaker ones after a connective. A single Chinese character that completes a word split
across two tokens (配|信, 组|合) gets a smaller value. Predictions are deliberately small,
because the activation is mostly near 0 and large guesses add more noise than signal.
Punctuation, Latin text, kana, and all other tokens predict 0.
"""

READS = ()

CONNECTIVES = {"和", "与", "及", "对", "将", "进行", "并", "有何", "举行了"}


def _han(s):
    return len(s) > 0 and all("一" <= ch <= "鿿" for ch in s)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not _han(tok) or len(prefix) < 2:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    if len(tok) == 1:
        return carry, 0.03 if (len(prev) == 1 and _han(prev)) else 0.0
    if len(tok) != 2:
        return carry, 0.0
    if prev.endswith("的"):
        return carry, 0.12
    if prev in CONNECTIVES:
        return carry, 0.06
    return carry, 0.0

programs.sol:
"""Approximate short t-initial spelling fragments, not a semantic topic.
TAK (especially Cyrillic так/Так) is positive; TUB, TB and TART/TORT
are negative. Weaker branches cover related endings and TALK.
Keep at most 32 letters of the unfinished word to join fragments across
tokens. Word boundaries, case, and fragment length change the response.
"""
import re
from anyascii import anyascii

READS = ()
LETTERS = r'[^\W\d_]+'


def next_word(word, token):
    if token.endswith(('\\t', '\\n')):
        return ''
    m = re.search(LETTERS + r'$', token)
    if not m:
        return ''
    return ((word if m.start() == 0 else '') + m.group())[-32:]


def response(word, token):
    m = re.search(LETTERS, token)
    if not m:
        return 0.0
    text = m.group()
