FIRST_LINE_BREAKS = {"\n\n", " \n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = (
        prefix.position == 0
        or prefix.document_ids[-2] != prefix.document_ids[-1]
    )
    if new_doc:
        seen, line = 0, 0
        if tok[:1].isupper() or tok[:1] == " ":
            value = -0.2
        elif tok[:1] and not tok[:1].isalnum():
            value = 0.15
        else:
            value = -0.05
    else:
        seen, line = carry
        value = 0.0
        if "\n" in tok and seen == 0:
            base = 0.35 if tok in FIRST_LINE_BREAKS else (0.0 if tok == ".\n\n" else 0.2)
            value = base * min(1.0, line / 60)
